export type AccountSection =
  | "asset"
  | "liability"
  | "equity"
  | "income"
  | "expense";

executableDefinitions.definition:
export function classifyAccountSection(
  type: AccountType | string | null | undefined,
  normalBalance: "debit" | "credit" | null | undefined,
): AccountSection | null {
  switch (type) {
    case "asset":
      return "asset";
    case "liability":
      return "liability";
    case "equity":
      return "equity";
    case "income":
      return "income";
    case "expense":
      return "expense";
    case "vat":
      return normalBalance === "debit" ? "asset" : "liability";
    default:
      return null;
  }
}

