export type AddBackupDestinationInput = {
  label: string;
  kind: string;
  location: string;
  inEeaOrEu: boolean;
  // Free-text human name behind the attestation (what the owner typed).
  attestedBy: string;
  // The resolved canonical actor id that actually ran the command
  // (user:… or agent:…). Recorded distinctly so the audit trail is honest
  // about whether a human or an agent created the attestation.
  actor?: string;
  regionCountry?: string;
  regionNote?: string;
  nonRelatedParty?: boolean;
  itSecurityMeetsStandards?: boolean;
  itSecurityNote?: string;
  at?: string;
};

export type AddBackupDestinationResult = {
  ok: boolean;
  destination?: BackupDestination;
  appliedRules: string[];
  errors: string[];
};

export type BackupDestination = {
  id: string;
  label: string;
  kind: BackupDestinationKind;
  location: string;
  // §4 stk.2: "ikke nærtstående part".
  nonRelatedParty: boolean;
  regionAttestation: RegionAttestation;
  itSecurityAttestation: ItSecurityAttestation | null;
  createdAt: string;
  createdBy: string;
  placements: BackupPlacement[];
};

export type BackupDestinationsFile = {
  version: "backup-destinations-v1";
  destinations: BackupDestination[];
};

export type BackupGovernanceStatus = {
  ok: boolean;
  appliedRules: string[];
  compliance: BackupComplianceStatus;
  lock: BackupLockEvaluation;
  destinations: BackupDestination[];
  destinationCount: number;
  compliantDestinationCount: number;
  hasCompliantDestination: boolean;
  // Whether the most recent backup has a verified placement at a
  // §4-compliant (EU/EEA, non-related, IT-secure) destination.
  latestBackupPlacedOffsite: boolean;
  latestBackupPlacementCount: number;
  checkedAt: string;
  errors: string[];
};

export type BackupLockConfig = {
  version: "backup-lock-v1";
  // Opt-in. When false, the lock never engages — only warnings are shown.
  enforced: boolean;
  // Extra days of leniency ON TOP of the 7-day legal window before the lock
  // actually blocks bookkeeping. 0 = lock exactly when the weekly window
  // lapses.
  graceDays: number;
  updatedAt: string | null;
  updatedBy: string | null;
};

export type BackupLockEvaluation = {
  enforced: boolean;
  locked: boolean;
  backupDue: boolean;
  graceDays: number;
  latestBackupAt: string | null;
  daysSinceLatestBackup: number | null;
  // Instant at which the lock engages (7-day window + grace). Null when no
  // backup is due.
  lockAt: string | null;
  checkedAt: string;
  reason: string;
  errors: string[];
};

export type BackupPlacement = {
  backupId: string;
  archiveSha256: string;
  archiveSizeBytes: number | null;
  placedAt: string;
  actor: string;
  actorKind: BackupPlacementActorKind;
  // verified = the archive was re-read at the destination and its sha256
  // matched. "declared" placements (agent pushed via a channel we cannot
  // read back) are recorded but not proven.
  verified: boolean;
  verifyMethod: "sha256-reread" | "remote-provider" | "declared";
  // Provider metadata is retained only after the adapter has independently
  // checked it and the downloaded object content. It never contains a token,
  // authorization header, provider error body, or archive bytes.
  remoteEvidence?: RemoteBackupEvidence;
  note: string | null;
};

export type ConfigureBackupLockResult = {
  ok: boolean;
  config?: BackupLockConfig;
  appliedRules: string[];
  errors: string[];
};

export type ConfirmBackupPlacementInput = {
  destinationId: string;
  backupId: string;
  archiveSha256: string;
  archiveSizeBytes?: number;
  actorKind?: BackupPlacementActorKind;
  actor?: string;
  at?: string;
  note?: string;
};

export type ConfirmBackupPlacementResult = {
  ok: boolean;
  placement?: BackupPlacement;
  appliedRules: string[];
  errors: string[];
};

export type ItSecurityAttestation = {
  // §4 stk.2: the third party must be presumed to meet recognised
  // IT-security standards.
  meetsRecognisedStandards: boolean;
  attestedBy: string;
  attestedAt: string;
  note: string | null;
};

export type PlaceBackupArchiveInput = {
  archivePath: string;
  destinationId: string;
  actorKind?: BackupPlacementActorKind;
  actor?: string;
  at?: string;
  note?: string;
};

export type PlaceBackupArchiveResult = {
  ok: boolean;
  placement?: BackupPlacement;
  copiedTo?: string;
  appliedRules: string[];
  errors: string[];
};

export type RegionAttestation = {
  // §4 stk.2: the server must sit in an EU/EEA country. Only a human can
  // truthfully assert this — Rentemester records the assertion.
  inEeaOrEu: boolean;
  country: string | null;
  attestedBy: string;
  attestedAt: string;
  note: string | null;
};

export type RemoveBackupDestinationResult = {
  ok: boolean;
  appliedRules: string[];
  errors: string[];
};

export type VerifyRemoteBackupPlacementInput = {
  destinationId: string;
  backupId: string;
  /** Provider object id only; all other object facts are derived locally. */
  remoteObjectId: string;
  actorKind?: BackupPlacementActorKind;
  actor?: string;
  at?: string;
  note?: string;
  maxMetadataAgeMs?: number;
};

export type ExpectedRemoteBackupObject = {
  provider: string;
  objectId: string;
  name: string;
  parentId: string;
  sizeBytes: number;
  checksumSha256: string;
};

export type RemoteBackupEvidence = {
  provider: string;
  objectId: string;
  name: string;
  parentId: string;
  sizeBytes: number;
  checksumSha256: string;
  metadataObservedAt: string;
  verifiedAt: string;
};

export type RemoteBackupObjectLookup =
  | { ok: true; metadata: RemoteBackupObjectMetadata }
  | { ok: false; failure: RemoteBackupProviderFailure };

export type RemoteBackupObjectMetadata = {
  objectId: string;
  name: string;
  parentId: string;
  sizeBytes: number;
  checksumSha256: string;
  // The provider must state when it obtained this metadata. This makes cached
  // metadata detectable instead of silently treating it as current evidence.
  observedAt: string;
};

export type RemoteBackupProviderAdapter = {
  provider: string;
  getObject(objectId: string): Promise<RemoteBackupObjectLookup>;
  readObjectContent(objectId: string): Promise<Uint8Array>;
};

export type BackupComplianceStatus = {
  ok: boolean;
  appliedRules: string[];
  latestBackupAt: string | null;
  latestBackupId: string | null;
  backupDue: boolean;
  hasActivitySinceBackup: boolean;
  daysSinceLatestBackup: number | null;
  requiredBy: string | null;
  checkedAt: string;
  backupsFound: number;
  evidence: {
    latestJournalEntryAt: string | null;
    latestDocumentAt: string | null;
    latestBankImportAt: string | null;
  };
  errors: string[];
};

