export type BudgetLine = {
  id: number;
  accountNo: string;
  accountName: string | null;
  period: string;
  amount: number;
  notes: string | null;
  createdAt: string;
};

export type BudgetVsActualLine = {
  accountNo: string;
  accountName: string | null;
  accountType: string | null;
  period: string;
  budget: number;
  actual: number;
  /** Signed variance — see the module header for the per-type convention. */
  variance: number;
};

export type BudgetVsActualReport = {
  ok: boolean;
  appliedRules: string[];
  periodStart: string;
  periodEnd: string;
  lines: BudgetVsActualLine[];
  totalBudget: number;
  totalActual: number;
  /** totalActual − totalBudget. Interpretation depends on the account mix. */
  totalVariance: number;
  errors: string[];
};

type EffectiveBudgetRow = {
  id: number;
  account_no: string;
  account_name: string | null;
  period: string;
  amount: number;
  notes: string | null;
  created_at: string;
};

export type ListBudgetResult = {
  ok: boolean;
  count: number;
  rows: BudgetLine[];
  errors: string[];
};

export type SetBudgetInput = {
  /** Account number the budget applies to — must exist in the chart of accounts. */
  accountNo: string;
  /** Calendar month in `YYYY-MM` form. */
  period: BudgetPeriod;
  /** Planned amount in kroner, in the account's natural sign (never negative). */
  amount: number;
  notes?: string;
  createdBy?: string;
  createdByProgram?: string;
};

export type SetBudgetResult = {
  ok: boolean;
  budgetLineId?: number;
  accountNo?: string;
  period?: string;
  amount?: number;
  appliedRules: string[];
  errors: string[];
};

