import {
  lookupCvrCompany,
  normalizeCvrNumber,
  type CvrCompanyInfo,
  type CvrLookupOptions,
} from "./cvr";

import {
  normalizeVatPeriodType,
  DEFAULT_VAT_PERIOD_TYPE,
