typeDefinitions.definition:
export type AccrualRegisterReport = {
  ok: boolean;
  accruals: AccrualRegisterRow[];
  totals: { totalAmount: number; recognizedAmount: number; remainingAmount: number };
  errors: string[];
};

export type AccrualRegisterRow = {
  accrualId: number;
  accrualType: AccrualType;
  description: string;
  totalAmount: number;
  recognitionPeriods: number;
  recognizedPeriods: number;
  recognizedAmount: number;
  remainingAmount: number;
  fullyRecognized: boolean;
  balanceAccountNo: string;
  resultAccountNo: string;
  firstRecognitionDate: string;
  periodStepMonths: number;
};

export type DueAccrualRecognitionPeriod = {
  accrualId: number;
  accrualType: AccrualType;
  description: string;
  periodIndex: number;
  totalPeriods: number;
  recognitionDate: string;
  amount: number;
  /** Days from `recognitionDate` to the as-of date; 0 when due today. */
  overdueDays: number;
};

export type DueAccrualRecognitionResult = {
  ok: boolean;
  asOfDate: string;
  periods: DueAccrualRecognitionPeriod[];
  /** Sum of `periods[].amount` — the income-statement effect still un-posted. */
  totalDueAmount: number;
  errors: string[];
};

export type AuditLogRow = {
  id: number;
  eventType: string;
  entityType: string;
  entityId: string | null;
  message: string;
  actor: string;
  createdAt: string;
};

export type BudgetVsActualLine = {
  accountNo: string;
  accountName: string | null;
  accountType: string | null;
  period: string;
  budget: number;
  actual: number;
  /** Signed variance — see the module header for the per-type convention. */
  variance: number;
};

export type BudgetVsActualReport = {
  ok: boolean;
  appliedRules: string[];
  periodStart: string;
  periodEnd: string;
  lines: BudgetVsActualLine[];
  totalBudget: number;
  totalActual: number;
  /** totalActual − totalBudget. Interpretation depends on the account mix. */
  totalVariance: number;
  errors: string[];
};

export type CompanySettings = {
  id: number;
  name: string;
  country: string;
  currency: string;
  cvr: string | null;
  fiscalYearStartMonth: number;
  fiscalYearLabelStrategy: FiscalYearLabelStrategy;
  /** CVR-register stamdata, last written by `company sync-cvr`. */
  address: string | null;
  postalCode: string | null;
  city: string | null;
  companyForm: string | null;
  industryCode: string | null;
  industryText: string | null;
  cvrStatus: string | null;
  auditWaived: boolean | null;
  /** ISO timestamp the CVR stamdata above was last synced; null when never. */
  cvrSyncedAt: string | null;
  /**
   * #221: the owner's own default payment terms — days from an invoice's issue
   * date to its due date. Captured once so every issued invoice inherits it.
   */
  paymentTermsDays: number;
  /**
   * #289: the VAT settlement cadence the company is registered for with SKAT
   * (`month` / `quarter` / `half-year`). Drives VAT period windows and their
   * filing deadlines. `null` means the company is NOT VAT-registered
   * (holding ApS, frivilligt momsfritaget, mikrovirksomhed under § 48); every
   * VAT-aware surface (dashboard, obligations, momsangivelse) gates on this.
   */
  vatPeriodType: VatPeriodType | null;
};

export type DashboardAuditStatus = {
  ok: boolean;
  entryCount: number;
  firstError?: string;
};

export type DashboardEuSalesOssStatus = {
  /** Net value (DKK) of cross-border B2B reverse-charge sales in the period. */
  euSalesValue: number;
  /** Number of EU customers on the recapitulative statement. */
  euCustomerCount: number;
  /** Net value (DKK) of OSS-classified EU consumer sales in the period. */
  ossConsumerSalesBase: number;
};

export type DashboardExceptionRow = {
  id: number;
  type: string;
  severity: string;
  status: string;
  message: string;
  /**
   * The concrete "what the owner must do" guidance — the most useful part of
   * an exception. Optional: rendered as "Sådan løser du den" when present, so
   * the static dashboard reaches parity with the Cockpit SPA (#270). The CLI
   * passes it through from `core/exceptions`' `required_action` column.
   */
  requiredAction?: string | null;
};

export type DashboardExceptionsResult = {
  ok: boolean;
  count: number;
  rows: DashboardExceptionRow[];
  errors: string[];
};

export type DashboardInput = {
  asOfDate: string;            // YYYY-MM-DD
  generatedAt: string;         // ISO 8601 UTC
  commitSha: string;           // 7-char short SHA or 'unknown'
  ruleBundleVersion: string;
  company: CompanySettings;
  invoices: InvoiceListResult;
  overdueInvoices: InvoiceListResult;
  unlinkedBank: BankTransactionListResult;
  exceptions: DashboardExceptionsResult;
  vatPeriod: VatPeriodReport;
  vatDaysRemaining: number;
  recentActivity: AuditLogRow[];
  backup: BackupComplianceStatus;
  audit: DashboardAuditStatus;
  /**
   * The recurring-feature inputs (#islands → control surfaces). All optional
   * so the render-engine and its existing fixtures stay backward-compatible:
   * a `DashboardInput` without them renders exactly the historical dashboard.
   * The CLI always supplies them.
   */
  payables?: PayablesListResult;
  accrualsDue?: DueAccrualRecognitionResult;
  accrualRegister?: AccrualRegisterReport;
  budgetVsActual?: BudgetVsActualReport;
  liquidity?: LiquidityForecastResult;
  tax?: DashboardTaxStatus;
  euSalesOss?: DashboardEuSalesOssStatus;
};

export type DashboardTaxStatus = {
  /** Fiscal-year label, e.g. "2025". */
  fiscalYearLabel: string;
  /** True once the fiscal year is closed and the tax return can be prepared. */
  available: boolean;
  /** Estimated corporate tax (selskabsskat), DKK — only when `available`. */
  corporateTax?: number | null;
  /** Bookkept årets resultat, DKK — only when `available`. */
  bookkeptResult?: number;
  /** Count of needs-review items — only when `available`. */
  needsReviewCount?: number;
};

export type RenderOptions = {
  // Currently only present for forward-compat. Render is deterministic from
  // input alone; the test suite still passes {} or no options at all.
  // (Kept as an explicit shape so future flags can be added without churn.)
};

export type InvoiceListResult = {
  ok: boolean;
  count: number;
  status: InvoiceQueryStatus;
  asOfDate?: string;
  query?: string;
  rows: InvoiceListRow[];
  errors: string[];
};

export type InvoiceListRow = {
  documentId: number;
  invoiceNumber: string;
  invoiceDate: string | null;
  customerName: string | null;
  customerCvr: string | null;
  /**
   * Buyer's EAN-number when set on the invoice payload, normalised to 13
   * digits. Surfaced here so the Cockpit can render a "Send som e-faktura"
   * action only on rows whose recipient is a public (EAN) buyer — the
   * normalisation lives in `core/ean.ts`.
   */
  buyerEanNumber: string | null;
  /**
   * `true` when the invoice payload marks the buyer as a public-recipient
   * (offentlig kunde), independent of whether an EAN-number was supplied.
   * Used together with `buyerEanNumber` so the cockpit shows the e-faktura
   * action only when both signals are present.
   */
  buyerPublicRecipient: boolean;
  /**
   * The most recent PEPPOL submission/transmission status for this invoice,
   * or `null` when none exists. Derived from the append-only
 * `peppol_submissions` reservation plus append-only delivery evidence.
   */
  peppolStatus: InvoicePeppolStatus | null;
  grossAmount: number;
  currency: string;
  openBalance: number;
  claimOpenBalance: number;
  status: "open" | "paid" | "credited" | "refunded" | "overpaid" | "written_off";
  effectiveDueDate: string | null;
  isOverdue: boolean;
  overdueDays: number;
};

export type InvoicePeppolStatus = {
  status: "queued" | "failed" | "uncertain" | "retryable" | "in_progress" | "acknowledged";
  submissionReference: string;
  transmissionId: string | null;
  acknowledgedAt: string | null;
};

export type LiquidityForecastPeriod = {
  /** Calendar month, `YYYY-MM`. */
  period: string;
  /** Bank balance carried into the month. */
  openingBalance: number;
  /** Open-invoice receipts expected to come due this month. */
  invoiceInflow: number;
  /** Recurring-invoice template generations projected to come due this month. */
  recurringInflow: number;
  /** Budgeted expense outflow for the month. */
  budgetedCostOutflow: number;
  /** Net change = invoiceInflow + recurringInflow − budgetedCostOutflow. */
  netChange: number;
  /** Projected bank balance at month end. */
  closingBalance: number;
};

export type LiquidityForecastResult = {
  ok: boolean;
  appliedRules: string[];
  startDate?: string;
  months?: number;
  /** The booked bank balance the day before startDate. */
  openingBalance: number;
  /** Projected balance at the end of the final period. */
  closingBalance: number;
  periods: LiquidityForecastPeriod[];
  errors: string[];
};

export type PayablesListResult = {
  ok: boolean;
  count: number;
  status: PayableQueryStatus;
  asOfDate: string;
  totalOpenBalance: number;
  overdueOpenBalance: number;
  notYetDueOpenBalance: number;
  rows: PayablesListRow[];
  errors: string[];
};

export type PayablesListRow = {
  payableId: number;
  documentId: number;
  billNo: string | null;
  billDate: string;
  dueDate: string;
  supplierName: string | null;
  vendorId: number | null;
  grossAmount: number;
  currency: string;
  paidAmount: number;
  openBalance: number;
  status: PayableStatus;
  isOverdue: boolean;
  overdueDays: number;
  agingBucket: PayableAgingBucket;
};

export type BankTransactionListResult = {
  ok: boolean;
  count: number;
  rows: Array<{
    id: number;
    transactionDate: string;
    bookingDate: string | null;
    text: string;
    amount: number;
    currency: string;
    reference: string | null;
    importBatchId: string | null;
    bankAccountId: number | null;
    ledgerStatus: string;
    reconciliationStatus: Exclude<ReconciliationStatus, "all">;
    journalEntryId: number | null;
    journalEntryNo: string | null;
  }>;
  errors: string[];
};

export type BackupComplianceStatus = {
  ok: boolean;
  appliedRules: string[];
  latestBackupAt: string | null;
  latestBackupId: string | null;
  backupDue: boolean;
  hasActivitySinceBackup: boolean;
  daysSinceLatestBackup: number | null;
  requiredBy: string | null;
  checkedAt: string;
  backupsFound: number;
  evidence: {
    latestJournalEntryAt: string | null;
    latestDocumentAt: string | null;
    latestBankImportAt: string | null;
  };
  errors: string[];
};

export type VatRubric = {
  salgsmoms: number;
  momsAfVarekobUdland: number;
  momsAfYdelseskobUdland: number;
  kobsmoms: number;
  momstilsvar: number;
  rubrikA: number;
  rubrikB: number;
  rubrikC: number;
};

export type VatPeriodReport = {
  ok: boolean;
  appliedRules: string[];
  periodStart: string;
  periodEnd: string;
  /** Registered cadence, null for a non-registered company. */
  vatPeriodType: VatPeriodType | null;
  /** Deadline only when the requested bounds equal one canonical VAT period. */
  filingDeadline: string | null;
  outputVat: number;
  inputVat: number;
  netVatPayable: number;
  purchaseBase25: number;
  salesBase25: number;
  /**
   * Combined value of all VAT-exempt reverse-charge sales (domestic + foreign).
   * Kept for backwards compatibility and human display ("Salg med omvendt
   * betalingspligt"). For the momsangivelse the two must be split — see
   * foreignReverseChargeSalesBase / domesticReverseChargeSalesBase below.
   */
  reverseChargeSalesBase: number;
  /**
   * JUR-2/KODE-2: value of FOREIGN reverse-charge sales — cross-border EU B2B
   * sales without Danish VAT (vat_code REVERSE_CHARGE_EXEMPT). These feed rubrik
   * B of the momsangivelse and are cross-checked against the EU sales list (VIES).
   */
  foreignReverseChargeSalesBase: number;
  /**
   * JUR-2/KODE-2: value of DOMESTIC reverse-charge sales — Danish §46 omvendt
   * betalingspligt (mobiltelefoner, CPU'er, metalskrot; vat_code
   * DOMESTIC_REVERSE_CHARGE_EXEMPT). These carry no Danish output VAT and feed
   * rubrik C ("værdi af andet salg uden moms"), NOT rubrik B, and must never
   * appear on the VIES EU sales list. Source: SKAT Den juridiske vejledning
   * A.B.3.3.1.5.
   */
  domesticReverseChargeSalesBase: number;
  /** EU service reverse-charge purchase base only. This feeds rubrik A;
   * non-EU services are kept separate below. */
  reverseChargePurchaseBase: number;
  /** EU goods acquisitions (§11), kept separate from service purchases (§46). */
  euGoodsAcquisitionPurchaseBase: number;
  /** Output VAT arising from §11 goods acquisitions, for the goods rubric. */
  euGoodsAcquisitionOutputVat: number;
  /** Service-purchase base from suppliers outside the EU. It contributes to
   * foreign-service reverse-charge VAT, but never to EU-only rubrik A. */
  nonEuServiceReverseChargePurchaseBase: number;
  /**
   * Output VAT allocated to foreign-service reverse charge (EU and non-EU).
   * A dedicated, source-proven VAT account supplies its booked amount; ledgers
   * where ordinary and reverse-charge output VAT share one account use the
   * øre-rounded VAT expected from each reverse-charge base line. The report
   * reconciles this category independently before it can be filed.
   */
  reverseChargePurchaseOutputVat: number;
  representationPurchaseBase: number;
  badDebtReliefBase25: number;
  /**
   * Value of VAT-exempt domestic sales (momsloven §13 — vat_code
   * DK_SALE_EXEMPT). These carry no output VAT and feed rubrik C of the
   * momsangivelse; they are kept out of the standard 25% sales base.
   */
  exemptSalesBase: number;
  /**
   * Value of digital-service sales to EU consumers handled under the OSS
   * scheme (vat_code OSS_EU_CONSUMER). These carry no Danish output VAT and
   * are reported via a separate OSS return — they are kept out of every
   * standard momsangivelse rubrik. See src/core/vat-oss.ts.
   */
  ossConsumerSalesBase: number;
  /** Number of journal entries that include an OSS_EU_CONSUMER line. */
  ossConsumerSalesEntryCount: number;
  journalEntryCount: number;
  reversedJournalEntryCount: number;
  reversalJournalEntryCount: number;
  totalJournalEntryCount: number;
  linesConsidered: number;
  reversedLinesConsidered: number;
  reversalLinesConsidered: number;
  totalLinesConsidered: number;
  /** Canonical SKAT rubric projection shared by report, filing and exports. */
  rubrikker: VatRubric;
  warnings: string[];
  errors: string[];
};

