export type OpenDbOptions = {
  /**
   * Normal ledgers use WAL. Disposable restore staging databases use DELETE so
   * Bun on Windows releases every filesystem handle before the atomic swap.
   */
  journalMode?: "WAL" | "DELETE";
};

