typeDefinitions.definition:
export type FiscalYear = {
  startYear: number;
  endYear: number;
  start: string;
  end: string;
  displayLabel: string;
  identifierLabel: string;
};

executableDefinitions.definition:
function pad2(value: number) {
  return String(value).padStart(2, "0");
}

function lastDayOfMonth(year: number, month: number) {
  return new Date(Date.UTC(year, month, 0)).toISOString().slice(0, 10);
}

export function annualReportDeadline(fiscalYearEnd: string): string {
  if (!isValidIsoDate(fiscalYearEnd)) throw new Error(`invalid ISO date: ${fiscalYearEnd}`);
  const year = Number(fiscalYearEnd.slice(0, 4));
  const month = Number(fiscalYearEnd.slice(5, 7));
  const day = Number(fiscalYearEnd.slice(8, 10));
  const monthIndex = month - 1 + 6;
  const targetYear = year + Math.floor(monthIndex / 12);
  const targetMonth = (monthIndex % 12) + 1;
  const lastDayTarget = lastDayOfMonth(targetYear, targetMonth);
  const endsOnLastDay = fiscalYearEnd === lastDayOfMonth(year, month);
  if (endsOnLastDay) return lastDayTarget;
  const clampedDay = Math.min(day, Number(lastDayTarget.slice(8, 10)));
  return `${targetYear}-${pad2(targetMonth)}-${pad2(clampedDay)}`;
}

export function fiscalYearForDate(
  dateText: string,
  startMonth: number,
  strategy: FiscalYearLabelStrategy,
): FiscalYear {
  if (!isValidIsoDate(dateText)) throw new Error(`invalid ISO date: ${dateText}`);
  const year = Number(dateText.slice(0, 4));
  const month = Number(dateText.slice(5, 7));
  const normalizedStartMonth = Number.isInteger(startMonth) && startMonth >= 1 && startMonth <= 12 ? startMonth : 1;
  const startYear = normalizedStartMonth === 1 || month >= normalizedStartMonth ? year : year - 1;
  const endYear = normalizedStartMonth === 1 ? startYear : startYear + 1;
  const displayLabel = strategy === "start-year"
    ? `${startYear}`
    : strategy === "span" && normalizedStartMonth !== 1
      ? `${startYear}/${String(endYear).slice(-2)}`
      : `${endYear}`;

  return {
    startYear,
    endYear,
    start: `${startYear}-${pad2(normalizedStartMonth)}-01`,
    end: normalizedStartMonth === 1
      ? `${endYear}-12-31`
      : lastDayOfMonth(endYear, normalizedStartMonth - 1),
    displayLabel,
    identifierLabel: displayLabel.replaceAll("/", "-"),
  };
}

typeDefinitions.definition:
export type CleanupRetryOptions = {
  maxAttempts?: number;
  sleep?: (milliseconds: number) => void;
};

executableDefinitions.definition:
function defaultSleep(milliseconds: number): void {
  Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, milliseconds);
}

function isTransientWindowsCleanupError(error: unknown): boolean {
  return Boolean(
    error && typeof error === "object" && "code" in error &&
      typeof error.code === "string" && TRANSIENT_WINDOWS_CLEANUP_CODES.has(error.code),
  );
}

export function retryTransientCleanup<T>(operation: () => T, options: CleanupRetryOptions = {}): T {
  const maxAttempts = options.maxAttempts ?? DEFAULT_BACKOFF_MS.length + 1;
  const sleep = options.sleep ?? defaultSleep;
  for (let attempt = 1; ; attempt += 1) {
    try {
      return operation();
    } catch (error) {
      if (!isTransientWindowsCleanupError(error) || attempt >= maxAttempts) throw error;
      sleep(DEFAULT_BACKOFF_MS[Math.min(attempt - 1, DEFAULT_BACKOFF_MS.length - 1)]!);
    }
  }
}

export function removePathWithRetry(path: string, options: RmOptions = { recursive: true, force: true }): void {
  retryTransientCleanup(() => rmSync(path, options));
}

export function renamePathWithRetry(source: string, destination: string): void {
  retryTransientCleanup(() => renameSync(source, destination));
}

export function closeThenCleanup(resource: ClosableResource | undefined, cleanup: () => void): void {
  resource?.close();
  cleanup();
}

export function closeThenRemovePath(resource: ClosableResource | undefined, path: string, options: RmOptions = { recursive: true, force: true }): void {
  closeThenCleanup(resource, () => removePathWithRetry(path, options));
}

