typeDefinitions.definition:
export type ArchiveBalanceLine = {
  lineNo: number;
  accountNo: string;
  accountName: string;
  amount: number;
};

export type ArchivePostingLine = {
  lineNo: number;
  accountNo: string;
  accountName: string;
  transactionDate: string;
  voucher: string;
  voucherType: string;
  text: string;
  vatType: string;
  amount: number;
  runningBalance: number | null;
};

export type ArchiveResult = {
  ok: boolean;
  /** Fiscal years newly written to the archive by this call. */
  archivedYears: number[];
  /** Fiscal years already present in the archive — left untouched. */
  skippedYears: number[];
  /** Ordered, human-readable description of what the archiving did. */
  auditTrail: string[];
  errors: string[];
};

export type ArchiveYear = {
  fiscalYear: number;
  postings: ArchivePostingLine[];
  balances: ArchiveBalanceLine[];
};

export type ArchivedYearView = {
  fiscalYear: number;
  sourceSystem: string;
  postingCount: number;
  balanceCount: number;
  importedAt: string;
  /** Present only when a specific `fiscalYear` was requested. */
  postings?: ArchivePostingLine[];
  /** Present only when a specific `fiscalYear` was requested. */
  balances?: ArchiveBalanceLine[];
};

export type ParseArchiveResult = {
  ok: boolean;
  /** The cut-over (latest) fiscal year — NOT archived; posted to the ledger. */
  cutOverYear: number | null;
  /** Pre-cut-over years, ascending by `fiscalYear` — deterministic. */
  years: ArchiveYear[];
  errors: string[];
};

export type QueryArchiveResult = {
  ok: boolean;
  years: ArchivedYearView[];
  errors: string[];
};

export type RollForwardBreak = {
  /** The closing year whose SaldoBalance is the "from" side of the comparison. */
  fromYear: number;
  /** The next year (or the cut-over year) whose Primobeholdning is the "to" side. */
  toYear: number;
  accountNo: string;
  /** The archived closing balance (kroner). */
  closingAmount: number;
  /** The opening balance the next year actually carries (kroner). */
  openingAmount: number;
};

export type RollForwardOptions = {
  /** Use parsed source balances before the archive is persisted. */
  closingBalances?: Map<number, Map<string, number>>;
  /** Source-chart types let preflight preserve the P&L/equity exclusion. */
  accountTypes?: Map<string, string>;
  /** Source-chart names are evidence for Dinero's explicit primo/asset groups. */
  accountNames?: Map<string, string>;
  /** Parser evidence only; DB role state must not make an import less strict. */
  accountRoleProposals?: Array<{ role: string; accountNo: string; source: string }>;
};

export type RollForwardResult = {
  ok: boolean;
  steps: RollForwardStep[];
  /** Flat list of every break across all steps, for a concise summary. */
  breaks: RollForwardBreak[];
  errors: string[];
};

export type RollForwardSourceConsolidation = {
  group: "fixed_asset";
  accountNos: string[];
  destinationAccountNo: string;
  closingAmount: number;
  openingAmount: number;
  perAccountDeltas: Array<{ accountNo: string; closingAmount: number; openingAmount: number }>;
};

export type RollForwardStep = {
  fromYear: number;
  toYear: number;
  /** True when the "to" year is the cut-over year (posted opening balance). */
  toIsCutOver: boolean;
  ok: boolean;
  breaks: RollForwardBreak[];
  /** VAT-account totals give the operator a second, grouped reconciliation view. */
  vatGroups: RollForwardVatGroup[];
  /** Source-evidenced fixed-asset groups consolidated onto their primo account. */
  sourceConsolidations?: RollForwardSourceConsolidation[];
};

export type RollForwardVatGroup = {
  group: "vat";
  closingAmount: number;
  openingAmount: number;
  difference: number;
  accountNos: string[];
  status: "continuous" | "explained_reclassification" | "explained_source_consolidation" | "unexplained";
  explanation?: {
    fiscalYear: number;
    voucher: string;
    transactionDate: string;
    voucherType: string;
    text: string;
    perAccountDeltas: Array<{ accountNo: string; closingAmount: number; openingAmount: number; voucherAmount: number }>;
    sourceAccountNos: string[];
    destinationAccountNo: string;
    transferAmount: number;
  };
  sourceConsolidation?: {
    fromYear: number;
    toYear: number;
    destinationAccountNo: string;
    perAccountDeltas: Array<{ accountNo: string; closingAmount: number; openingAmount: number }>;
  };
};

export type ArchiveIntegrityEvidence = {
  archiveSha256: string;
  archiveEntryCount: number;
  extractedEntryCount: number;
  importedEntryCount: number;
  archiveListingSha256: string;
  extractedManifestSha256: string;
};

export type ImportArtifact = {
  /** Export-root-relative, forward-slash file name, e.g. "2025/Kontoplan.csv". */
  name: string;
  /** Absolute path on disk. */
  path: string;
  /** Raw file bytes. */
  bytes: Uint8Array;
  /** BOM-stripped UTF-8 decode of `bytes`. */
  text: string;
};

export type MultiArtifactSource = {
  rootDir: string;
  files: Record<string, ImportArtifact>;
  /** Immutable, canonical evidence for the exact resolved input. */
  sourceEvidence: SourceEvidence;
  /**
   * Present for a ZIP source after its complete archive listing and extraction
   * have been verified. The three counts must agree before parsing can begin.
   */
  archiveIntegrity?: ArchiveIntegrityEvidence;
};

export type SourceEvidence = {
  sourceKind: "zip" | "directory" | "file";
  canonicalInventorySha256: string;
  entries: SourceEvidenceEntry[];
  importedEntryCount: number;
  totalUncompressedBytes: number;
  /** Present only for a ZIP's private immutable snapshot. */
  rawSha256?: string;
  /** Present only for a ZIP's private immutable snapshot. */
  rawSize?: number;
  /** Present only for ZIP file entries after strict path normalization. */
  canonicalListingSha256?: string;
  /** Present only for ZIP file entries after strict path normalization. */
  listingEntryCount?: number;
  /** Present only for ZIP sources. */
  extractedEntryCount?: number;
};

export type SourceEvidenceEntry = {
  path: string;
  size: number;
  sha256: string;
};

