executableDefinitions.definition:
function splitRecord(line: string): string[] {
  return line.split(";").map((cell) => cell.trim());
}

function parseBelob(cell: string): number | null | undefined {
  const trimmed = cell.trim();
  if (trimmed.length === 0) return undefined;
  const normalised = trimmed.replace(",", ".");
  if (!/^-?\d+(\.\d+)?$/.test(normalised)) return null;
  const value = Number(normalised);
  return Number.isFinite(value) ? value : null;
}

function toOreInt(kroner: number): number {
  return Math.round(kroner * SCALE);
}

function discoverYears(input: MultiArtifactSource): number[] {
  const years = new Set<number>();
  for (const name of Object.keys(input.files)) {
    const match = /^(\d{4})\/Posteringer\.csv$/i.exec(name);
    if (match) years.add(Number(match[1]));
  }
  return [...years].sort((a, b) => a - b);
}

function parsePosteringer(text: string, sourceName: string, errors: string[]): ArchivePostingLine[] {
  const out: ArchivePostingLine[] = [];
  const lines = text.split(/\r?\n/);
  let sawHeader = false;
  let lineNo = 0;
  for (let i = 0; i < lines.length; i += 1) {
    const line = lines[i]!.trim();
    if (line.length === 0) continue;
    const cells = splitRecord(line);
    if (!sawHeader) {
      if ((cells[0] ?? "").toLowerCase() === "konto") {
        sawHeader = true;
        continue;
      }
      errors.push(`${sourceName}: missing the 'Konto;Kontonavn;Dato;...' header row`);
      return [];
    }
    const accountNo = cells[0] ?? "";
    if (!accountNo) {
      errors.push(`${sourceName} line ${i + 1}: posting row is missing a Konto`);
      continue;
    }
    const amount = parseBelob(cells[7] ?? "");
    if (amount === null) {
      errors.push(
        `${sourceName} line ${i + 1}: posting row for account '${accountNo}' has an invalid Beløb '${cells[7] ?? ""}'`,
      );
      continue;
    }
    const runningBalance = parseBelob(cells[8] ?? "");
    if (runningBalance === null) {
      errors.push(
        `${sourceName} line ${i + 1}: posting row for account '${accountNo}' has an invalid Saldo '${cells[8] ?? ""}'`,
      );
      continue;
    }
    out.push({
      lineNo,
      accountNo,
      accountName: cells[1] ?? "",
      transactionDate: cells[2] ?? "",
      voucher: cells[3] ?? "",
      voucherType: cells[4] ?? "",
      text: cells[5] ?? "",
      vatType: cells[6] ?? "",
      amount: amount ?? 0,
      runningBalance: runningBalance ?? null,
    });
    lineNo += 1;
  }
  if (!sawHeader) {
    errors.push(`${sourceName}: missing the 'Konto;Kontonavn;Dato;...' header row`);
  }
  return out;
}

function parseSaldoBalance(
  text: string,
  sourceName: string,
  errors: string[],
): ArchiveBalanceLine[] {
  const out: ArchiveBalanceLine[] = [];
  const lines = text.split(/\r?\n/);
  let sawHeader = false;
  let lineNo = 0;
  for (let i = 0; i < lines.length; i += 1) {
    const line = lines[i]!.trim();
    if (line.length === 0) continue;
    const cells = splitRecord(line);
    if (!sawHeader) {
      if ((cells[0] ?? "").toLowerCase() === "konto") {
        sawHeader = true;
        continue;
      }
      errors.push(`${sourceName}: missing the 'Konto;Kontonavn;Beløb' header row`);
      return [];
    }
    const accountNo = cells[0] ?? "";
    if (!accountNo) {
      errors.push(`${sourceName} line ${i + 1}: balance row is missing a Konto`);
      continue;
    }
    const amount = parseBelob(cells[2] ?? "");
    if (amount === null || amount === undefined) {
      errors.push(
        `${sourceName} line ${i + 1}: balance row for account '${accountNo}' has an invalid Beløb '${cells[2] ?? ""}'`,
      );
      continue;
    }
    out.push({ lineNo, accountNo, accountName: cells[1] ?? "", amount });
    lineNo += 1;
  }
  if (!sawHeader) {
    errors.push(`${sourceName}: missing the 'Konto;Kontonavn;Beløb' header row`);
  }
  return out;
}

function primobeholdningOf(text: string): Map<string, number> {
  const map = new Map<string, number>();
  const lines = text.split(/\r?\n/);
  let sawHeader = false;
  for (const raw of lines) {
    const line = raw.trim();
    if (line.length === 0) continue;
    const cells = splitRecord(line);
    if (!sawHeader) {
      if ((cells[0] ?? "").toLowerCase() === "konto") sawHeader = true;
      continue;
    }
    const accountNo = cells[0] ?? "";
    const voucher = (cells[3] ?? "").trim();
    const text2 = (cells[5] ?? "").trim().toLowerCase();
    if (voucher !== "0" || text2 !== "primobeholdning") continue;
    const amount = parseBelob(cells[7] ?? "");
    if (typeof amount === "number" && accountNo) map.set(accountNo, amount);
  }
  return map;
}

export function parseArchiveYears(input: MultiArtifactSource): ParseArchiveResult {
  const errors: string[] = [];
  const allYears = discoverYears(input);
  if (allYears.length === 0) {
    return { ok: true, cutOverYear: null, years: [], errors: [] };
  }
  const cutOverYear = allYears[allYears.length - 1]!;
  const preCutOver = allYears.slice(0, -1);

  const years: ArchiveYear[] = [];
  for (const year of preCutOver) {
    const posteringer = input.files[`${year}/Posteringer.csv`];
    if (!posteringer) {
      errors.push(`pre-cut-over year ${year} is missing Posteringer.csv`);
      continue;
    }
    const postings = parsePosteringer(posteringer.text, `${year}/Posteringer.csv`, errors);
    const saldoBalance = input.files[`${year}/SaldoBalance.csv`];
    const balances = saldoBalance
      ? parseSaldoBalance(saldoBalance.text, `${year}/SaldoBalance.csv`, errors)
      : [];
    years.push({ fiscalYear: year, postings, balances });
  }

  return { ok: errors.length === 0, cutOverYear, years, errors };
}

export function archiveDineroYears(db: Database, input: MultiArtifactSource): ArchiveResult {
  const auditTrail: string[] = [];
  const parsed = parseArchiveYears(input);
  if (!parsed.ok) {
    return {
      ok: false,
      archivedYears: [],
      skippedYears: [],
      auditTrail,
      errors: parsed.errors,
    };
  }

  if (parsed.years.length === 0) {
    auditTrail.push(
      parsed.cutOverYear == null
        ? "Export carries no fiscal-year folders — nothing to archive"
        : `Export carries only the cut-over year ${parsed.cutOverYear} — nothing to archive`,
    );
    return { ok: true, archivedYears: [], skippedYears: [], auditTrail, errors: [] };
  }

  const archivedYears: number[] = [];
  const skippedYears: number[] = [];

  const existsStmt = db.query(
    "SELECT id FROM import_archive_years WHERE source_system = ? AND fiscal_year = ?",
  );
  const insertYear = db.query(
    `INSERT INTO import_archive_years (source_system, fiscal_year, posting_count, balance_count)
     VALUES (?, ?, ?, ?)`,
  );
  const insertPosting = db.query(
    `INSERT INTO import_archive_postings
       (archive_year_id, line_no, account_no, account_name, transaction_date,
        voucher, voucher_type, text, vat_type, amount, running_balance)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
  );
  const insertBalance = db.query(
    `INSERT INTO import_archive_balances
       (archive_year_id, line_no, account_no, account_name, amount)
     VALUES (?, ?, ?, ?, ?)`,
  );

  const persist = db.transaction((years: ArchiveYear[]) => {
    for (const year of years) {
      if (existsStmt.get(SYSTEM, year.fiscalYear)) {
        skippedYears.push(year.fiscalYear);
        auditTrail.push(`Fiscal year ${year.fiscalYear} already archived — skipped`);
        continue;
      }
      const info = insertYear.run(
        SYSTEM,
        year.fiscalYear,
        year.postings.length,
        year.balances.length,
      );
      const yearId = Number(info.lastInsertRowid);
      for (const p of year.postings) {
        insertPosting.run(
          yearId,
          p.lineNo,
          p.accountNo,
          p.accountName,
          p.transactionDate,
          p.voucher,
          p.voucherType,
          p.text,
          p.vatType,
          p.amount,
          p.runningBalance,
        );
      }
      for (const b of year.balances) {
        insertBalance.run(yearId, b.lineNo, b.accountNo, b.accountName, b.amount);
      }
      archivedYears.push(year.fiscalYear);
      auditTrail.push(
        `Archived fiscal year ${year.fiscalYear}: ${year.postings.length} posting(s), ` +
          `${year.balances.length} closing-balance line(s) — read-only, not posted`,
      );
    }
  });
  persist(parsed.years);

  return { ok: true, archivedYears, skippedYears, auditTrail, errors: [] };
}

export function queryArchive(
  db: Database,
  options: { sourceSystem?: string; fiscalYear?: number } = {},
): QueryArchiveResult {
  const sourceSystem = options.sourceSystem ?? SYSTEM;
  const headerRows = db
    .query(
      `SELECT id, fiscal_year, source_system, posting_count, balance_count, imported_at
         FROM import_archive_years
        WHERE source_system = ?
          ${options.fiscalYear != null ? "AND fiscal_year = ?" : ""}
        ORDER BY fiscal_year ASC`,
    )
    .all(
      ...(options.fiscalYear != null ? [sourceSystem, options.fiscalYear] : [sourceSystem]),
    ) as Array<{
    id: number;
    fiscal_year: number;
    source_system: string;
    posting_count: number;
    balance_count: number;
    imported_at: string;
  }>;

  if (options.fiscalYear != null && headerRows.length === 0) {
    return {
      ok: false,
      years: [],
      errors: [`no archived ${sourceSystem} data for fiscal year ${options.fiscalYear}`],
    };
  }

  const years: ArchivedYearView[] = headerRows.map((row) => {
    const view: ArchivedYearView = {
      fiscalYear: row.fiscal_year,
      sourceSystem: row.source_system,
      postingCount: row.posting_count,
      balanceCount: row.balance_count,
      importedAt: row.imported_at,
    };
    if (options.fiscalYear != null) {
      view.postings = (
        db
          .query(
            `SELECT line_no, account_no, account_name, transaction_date, voucher,
                    voucher_type, text, vat_type, amount, running_balance
               FROM import_archive_postings
              WHERE archive_year_id = ?
              ORDER BY line_no ASC`,
          )
          .all(row.id) as Array<Record<string, unknown>>
      ).map((p) => ({
        lineNo: p.line_no as number,
        accountNo: p.account_no as string,
        accountName: (p.account_name as string) ?? "",
        transactionDate: (p.transaction_date as string) ?? "",
        voucher: (p.voucher as string) ?? "",
        voucherType: (p.voucher_type as string) ?? "",
        text: (p.text as string) ?? "",
        vatType: (p.vat_type as string) ?? "",
        amount: p.amount as number,
        runningBalance: (p.running_balance as number | null) ?? null,
      }));
      view.balances = (
        db
          .query(
            `SELECT line_no, account_no, account_name, amount
               FROM import_archive_balances
              WHERE archive_year_id = ?
              ORDER BY line_no ASC`,
          )
          .all(row.id) as Array<Record<string, unknown>>
      ).map((b) => ({
        lineNo: b.line_no as number,
        accountNo: b.account_no as string,
        accountName: (b.account_name as string) ?? "",
        amount: b.amount as number,
      }));
    }
    return view;
  });

  return { ok: true, years, errors: [] };
}

function isOpeningPosting(posting: ArchivePostingLine): boolean {
  return posting.voucher === "0" && posting.text.trim().toLowerCase() === "primobeholdning";
}

function resolveVatGroup(
  closing: Map<string, number>, opening: Map<string, number>, accountTypeOf: (accountNo: string) => string | null,
  proposals: RollForwardOptions["accountRoleProposals"],
): { accountNos: string[]; settlement: string } | null {
  const vatAccounts = [...new Set([...closing.keys(), ...opening.keys()])].filter((accountNo) => accountTypeOf(accountNo) === "vat").sort();
  const settlements = (proposals ?? []).filter((proposal) => proposal.role === "vat_settlement" && proposal.accountNo && accountTypeOf(proposal.accountNo) !== "vat");
  return vatAccounts.length > 0 && settlements.length === 1 ? { accountNos: [...vatAccounts, settlements[0]!.accountNo].sort(), settlement: settlements[0]!.accountNo } : null;
}

function explainSourceVatConsolidation(
  input: MultiArtifactSource,
  fromYear: number,
  toYear: number,
  closing: Map<string, number>,
  opening: Map<string, number>,
  accountTypeOf: (accountNo: string) => string | null,
  proposals: RollForwardOptions["accountRoleProposals"],
): RollForwardVatGroup["sourceConsolidation"] | null {
  const group = resolveVatGroup(closing, opening, accountTypeOf, proposals);
  if (!group) return null;
  const fromFile = input.files[`${fromYear}/Posteringer.csv`];
  if (!fromFile) return null;
  const parseErrors: string[] = [];
  const automaticTransfers = parsePosteringer(
    fromFile.text,
    `${fromYear}/Posteringer.csv`,
    parseErrors,
  ).filter((posting) =>
    posting.voucher === "0" &&
    posting.transactionDate === `${fromYear}-12-31` &&
    group.accountNos.includes(posting.accountNo) &&
    /^overført (til|fra) /i.test(posting.text.trim()),
  );
  if (parseErrors.length > 0 || automaticTransfers.length < 2) return null;
  if (automaticTransfers.reduce((sum, posting) => sum + toOreInt(posting.amount), 0) !== 0) return null;
  const controlAccounts = group.accountNos.filter((accountNo) => accountNo !== group.settlement);
  if (controlAccounts.length === 0) return null;
  if (controlAccounts.some((accountNo) => toOreInt(opening.get(accountNo) ?? 0) !== 0)) return null;
  const closingTotal = group.accountNos.reduce((sum, accountNo) => sum + toOreInt(closing.get(accountNo) ?? 0), 0);
  const openingTotal = group.accountNos.reduce((sum, accountNo) => sum + toOreInt(opening.get(accountNo) ?? 0), 0);
  if (closingTotal !== openingTotal) return null;
  const changed = group.accountNos.some(
    (accountNo) => toOreInt(closing.get(accountNo) ?? 0) !== toOreInt(opening.get(accountNo) ?? 0),
  );
  if (!changed) return null;
  return {
    fromYear,
    toYear,
    destinationAccountNo: group.settlement,
    perAccountDeltas: group.accountNos.map((accountNo) => ({
      accountNo,
      closingAmount: closing.get(accountNo) ?? 0,
      openingAmount: opening.get(accountNo) ?? 0,
    })),
  };
}

function explainSourceFixedAssetConsolidations(
  closing: Map<string, number>,
  opening: Map<string, number>,
  accountTypeOf: (accountNo: string) => string | null,
  accountNames: Map<string, string> | undefined,
): RollForwardSourceConsolidation[] {
  if (!accountNames) return [];
  const present = [...new Set([...closing.keys(), ...opening.keys()])];
  const results: RollForwardSourceConsolidation[] = [];
  for (const destinationAccountNo of present.sort()) {
    const destinationName = accountNames.get(destinationAccountNo)?.trim() ?? "";
    if (!/^\d{5}$/.test(destinationAccountNo) || !destinationAccountNo.endsWith("00")) continue;
    if (accountTypeOf(destinationAccountNo) !== "asset" || !/\bprimo\b/i.test(destinationName)) continue;
    const family = destinationAccountNo.slice(0, 3);
    const accountNos = present.filter((accountNo) =>
      accountNo.startsWith(family) &&
      accountTypeOf(accountNo) === "asset" &&
      accountNames.has(accountNo),
    ).sort();
    if (accountNos.length < 2) continue;
    const otherAccounts = accountNos.filter((accountNo) => accountNo !== destinationAccountNo);
    if (otherAccounts.some((accountNo) => !/(tilgang i året|afgang i året|afskrivninger)/i.test(accountNames.get(accountNo) ?? ""))) continue;
    if (otherAccounts.some((accountNo) => toOreInt(opening.get(accountNo) ?? 0) !== 0)) continue;
    if (!otherAccounts.some((accountNo) => toOreInt(closing.get(accountNo) ?? 0) !== 0)) continue;
    const closingOre = accountNos.reduce((sum, accountNo) => sum + toOreInt(closing.get(accountNo) ?? 0), 0);
    const openingOre = accountNos.reduce((sum, accountNo) => sum + toOreInt(opening.get(accountNo) ?? 0), 0);
    if (closingOre !== openingOre) continue;
    results.push({
      group: "fixed_asset",
      accountNos,
      destinationAccountNo,
      closingAmount: Number(closingOre) / 100,
      openingAmount: Number(openingOre) / 100,
      perAccountDeltas: accountNos.map((accountNo) => ({
        accountNo,
        closingAmount: closing.get(accountNo) ?? 0,
        openingAmount: opening.get(accountNo) ?? 0,
      })),
    });
  }
  return results;
}

function explainVatReclassification(
  input: MultiArtifactSource,
  fromYear: number,
  toYear: number,
  closing: Map<string, number>,
  opening: Map<string, number>,
  accountTypeOf: (accountNo: string) => string | null,
  proposals: RollForwardOptions["accountRoleProposals"],
): { accountNos: string[]; fiscalYear: number; voucher: string; lines: ArchivePostingLine[] } | null {
  const group = resolveVatGroup(closing, opening, accountTypeOf, proposals);
  // Multiple equally plausible settlement proposals are accounting ambiguity,
  // not permission to silently net balances.
  if (!group) return null;
  const accountNos = group.accountNos;
  const expected = new Map<string, number>();
  for (const accountNo of accountNos) {
    const delta = toOreInt((opening.get(accountNo) ?? 0) - (closing.get(accountNo) ?? 0));
    if (delta !== 0) expected.set(accountNo, delta);
  }
  if (expected.size === 0) return null;

  const fromFile = input.files[`${fromYear}/Posteringer.csv`];
  const toFile = input.files[`${toYear}/Posteringer.csv`];
  if (!fromFile || !toFile) return null;
  const parseErrors: string[] = [];
  const boundaryDates = new Set([`${fromYear}-12-31`, `${toYear}-01-01`]);
  const postings = [
    ...parsePosteringer(fromFile.text, `${fromYear}/Posteringer.csv`, parseErrors).map((posting) => ({ ...posting, fiscalYear: fromYear })),
    ...parsePosteringer(toFile.text, `${toYear}/Posteringer.csv`, parseErrors).map((posting) => ({ ...posting, fiscalYear: toYear })),
  ].filter((posting) => !isOpeningPosting(posting));
  if (parseErrors.length > 0) return null;
  const byVoucher = new Map<string, Array<ArchivePostingLine & { fiscalYear: number }>>();
  for (const posting of postings) {
    if (!posting.voucher || !boundaryDates.has(posting.transactionDate) || toOreInt(posting.amount) === 0) continue;
    const key = `${posting.fiscalYear}\u0000${posting.voucher}`;
    const group = byVoucher.get(key) ?? [];
    group.push(posting);
    byVoucher.set(key, group);
  }
  const matches: Array<{ accountNos: string[]; fiscalYear: number; voucher: string; lines: ArchivePostingLine[] }> = [];
  for (const lines of byVoucher.values()) {
    if (lines.some((line) => !accountNos.includes(line.accountNo))) continue;
    const amounts = new Map<string, number>();
    for (const line of lines) amounts.set(line.accountNo, (amounts.get(line.accountNo) ?? 0) + toOreInt(line.amount));
    if ([...amounts.values()].reduce((sum, amount) => sum + amount, 0) !== 0) continue;
    if (amounts.size !== expected.size) continue;
    if ([...expected].every(([accountNo, amount]) => amounts.get(accountNo) === amount)) {
      matches.push({ accountNos, fiscalYear: lines[0]!.fiscalYear, voucher: lines[0]!.voucher, lines });
    }
  }
  return matches.length === 1 ? matches[0]! : null;
}

function compareRollForward(
  fromYear: number,
  toYear: number,
  closing: Map<string, number>,
  opening: Map<string, number>,
  accountTypeOf: (accountNo: string) => string | null,
): RollForwardBreak[] {
  const breaks: RollForwardBreak[] = [];
  const accounts = new Set<string>([...closing.keys(), ...opening.keys()]);
  for (const accountNo of [...accounts].sort()) {
    const type = accountTypeOf(accountNo);
    // P&L og equity ruller IKKE forward — skip dem.
    if (type === "income" || type === "expense" || type === "equity") continue;
    const closingAmount = closing.get(accountNo) ?? 0;
    const openingAmount = opening.get(accountNo) ?? 0;
    if (toOreInt(closingAmount) !== toOreInt(openingAmount)) {
      breaks.push({ fromYear, toYear, accountNo, closingAmount, openingAmount });
    }
  }
  return breaks;
}

function vatGroupEvidence(
  closing: Map<string, number>,
  opening: Map<string, number>,
  accountTypeOf: (accountNo: string) => string | null,
): RollForwardVatGroup[] {
  const accountNos = [...new Set([...closing.keys(), ...opening.keys()])]
    .filter((accountNo) => accountTypeOf(accountNo) === "vat" || /^(64000|64020|64040|64060)$/.test(accountNo))
    .sort();
  if (accountNos.length === 0) return [];
  const closingAmount = accountNos.reduce((sum, accountNo) => sum + (closing.get(accountNo) ?? 0), 0);
  const openingAmount = accountNos.reduce((sum, accountNo) => sum + (opening.get(accountNo) ?? 0), 0);
  return [{ group: "vat", closingAmount, openingAmount, difference: closingAmount - openingAmount, accountNos, status: "unexplained" }];
}

export function checkRollForward(
  db: Database,
  input: MultiArtifactSource,
  options: RollForwardOptions = {},
): RollForwardResult {
  const errors: string[] = [];
  const allYears = discoverYears(input);
  if (allYears.length < 2) {
    // Nothing to roll forward: a single-year (or empty) export.
    return { ok: true, steps: [], breaks: [], errors: [] };
  }
  const cutOverYear = allYears[allYears.length - 1]!;

  // Archived closing balances, keyed by fiscal year.
  const closingByYear = options.closingBalances ?? new Map<number, Map<string, number>>();
  if (!options.closingBalances) {
    const archivedRows = db
      .query(
        `SELECT y.fiscal_year AS fiscal_year, b.account_no AS account_no, b.amount AS amount
           FROM import_archive_balances b
           JOIN import_archive_years y ON y.id = b.archive_year_id
          WHERE y.source_system = ?`,
      )
      .all(SYSTEM) as Array<{ fiscal_year: number; account_no: string; amount: number }>;
    for (const row of archivedRows) {
      let map = closingByYear.get(row.fiscal_year);
      if (!map) {
        map = new Map<string, number>();
        closingByYear.set(row.fiscal_year, map);
      }
      map.set(row.account_no, row.amount);
    }
  }

  // Opening Primobeholdning, keyed by fiscal year, straight from the export.
  const openingByYear = new Map<number, Map<string, number>>();
  for (const year of allYears) {
    const file = input.files[`${year}/Posteringer.csv`];
    if (file) openingByYear.set(year, primobeholdningOf(file.text));
  }

  // #198 — slå konto-type op én gang og giv det videre til compareRollForward.
  // `accounts`-tabellen er authoritative efter Dinero-parseren har reconcileret
  // chart-of-accounts (#193). Ukendte konti (ikke endnu seedet) returnerer
  // null, og compareRollForward behandler dem som balance-sheet (konservativt:
  // hellere false-positivt advare end at gemme et reelt brud).
  const accountTypes = new Map<string, string>();
  const typeRows = db
    .query("SELECT account_no AS accountNo, type AS type FROM accounts")
    .all() as Array<{ accountNo: string; type: string }>;
  for (const row of typeRows) {
    accountTypes.set(row.accountNo, row.type);
  }
  const accountTypeOf = (accountNo: string): string | null =>
    options.accountTypes?.get(accountNo) ?? accountTypes.get(accountNo) ?? null;

  const steps: RollForwardStep[] = [];
  const allBreaks: RollForwardBreak[] = [];
  // Roll each archived year's closing balance into the next year's opening.
  for (let i = 0; i < allYears.length - 1; i += 1) {
    const fromYear = allYears[i]!;
    const toYear = allYears[i + 1]!;
    const closing = closingByYear.get(fromYear);
    if (!closing) {
      errors.push(
        `fiscal year ${fromYear} has no archived SaldoBalance — cannot verify roll-forward into ${toYear}`,
      );
      continue;
    }
    const opening = openingByYear.get(toYear);
    if (!opening) {
      errors.push(`fiscal year ${toYear} has no Posteringer.csv — cannot read its opening balance`);
      continue;
    }
    let breaks = compareRollForward(fromYear, toYear, closing, opening, accountTypeOf);
    const sourceConsolidations = explainSourceFixedAssetConsolidations(
      closing, opening, accountTypeOf, options.accountNames,
    );
    for (const consolidation of sourceConsolidations) {
      const group = new Set(consolidation.accountNos);
      breaks = breaks.filter((item) => !group.has(item.accountNo));
    }
    const vatGroup = resolveVatGroup(closing, opening, accountTypeOf, options.accountRoleProposals);
    const explanation = explainVatReclassification(
      input, fromYear, toYear, closing, opening, accountTypeOf, options.accountRoleProposals,
    );
    const sourceConsolidation = explanation ? null : explainSourceVatConsolidation(
      input, fromYear, toYear, closing, opening, accountTypeOf, options.accountRoleProposals,
    );
    const explainedAccountNos = explanation?.accountNos ?? (sourceConsolidation
      ? resolveVatGroup(closing, opening, accountTypeOf, options.accountRoleProposals)?.accountNos
      : undefined);
    if (explainedAccountNos) {
      const group = new Set(explainedAccountNos);
      // Only the complete group may be removed. Any unrelated or partially
      // explained member remains a fatal roll-forward break.
      const groupBreaks = breaks.filter((item) => group.has(item.accountNo));
      if (groupBreaks.length > 0 && groupBreaks.every((item) => group.has(item.accountNo))) {
        breaks = breaks.filter((item) => !group.has(item.accountNo));
      }
    }
    steps.push({
      fromYear,
      toYear,
      toIsCutOver: toYear === cutOverYear,
      ok: breaks.length === 0,
      breaks,
      ...(sourceConsolidations.length > 0 ? { sourceConsolidations } : {}),
      vatGroups: (() => {
        const accountNos = explanation?.accountNos ?? vatGroup?.accountNos ?? vatGroupEvidence(closing, opening, accountTypeOf)[0]?.accountNos ?? [];
        if (accountNos.length === 0) return [];
        const closingAmount = accountNos.reduce((sum, accountNo) => sum + (closing.get(accountNo) ?? 0), 0);
        const openingAmount = accountNos.reduce((sum, accountNo) => sum + (opening.get(accountNo) ?? 0), 0);
        const voucherAmounts = new Map<string, number>();
        for (const line of explanation?.lines ?? []) voucherAmounts.set(line.accountNo, (voucherAmounts.get(line.accountNo) ?? 0) + line.amount);
        return [{
          group: "vat" as const, closingAmount, openingAmount, difference: closingAmount - openingAmount, accountNos,
          status: explanation
            ? "explained_reclassification" as const
            : sourceConsolidation
              ? "explained_source_consolidation" as const
              : breaks.some((item) => accountNos.includes(item.accountNo)) ? "unexplained" as const : "continuous" as const,
          ...(explanation ? { explanation: {
            fiscalYear: explanation.fiscalYear, voucher: explanation.voucher,
            transactionDate: explanation.lines[0]!.transactionDate, voucherType: explanation.lines[0]!.voucherType,
            text: explanation.lines[0]!.text,
            sourceAccountNos: accountNos.filter((accountNo) => accountNo !== vatGroup?.settlement), destinationAccountNo: vatGroup?.settlement ?? "",
            transferAmount: voucherAmounts.get(vatGroup?.settlement ?? "") ?? 0,
            perAccountDeltas: accountNos.map((accountNo) => ({ accountNo, closingAmount: closing.get(accountNo) ?? 0, openingAmount: opening.get(accountNo) ?? 0, voucherAmount: voucherAmounts.get(accountNo) ?? 0 })),
          } } : {}),
          ...(sourceConsolidation ? { sourceConsolidation } : {}),
        }];
      })(),
    });
    allBreaks.push(...breaks);
  }

  return {
    ok: errors.length === 0 && allBreaks.length === 0,
    steps,
    breaks: allBreaks,
    errors,
  };
}

export function describeRollForward(result: RollForwardResult): string[] {
  const lines: string[] = [];
  for (const step of result.steps) {
    const target = step.toIsCutOver ? `cut-over year ${step.toYear}` : `${step.toYear}`;
    const explained = step.vatGroups.find((group) => group.status === "explained_reclassification");
    const consolidated = step.vatGroups.find((group) => group.status === "explained_source_consolidation");
    if (step.ok && explained?.explanation) {
      lines.push(`Roll-forward ${step.fromYear} -> ${target}: VAT group continuity documented by reclassification voucher ${explained.explanation.fiscalYear}/${explained.explanation.voucher}`);
    } else if (step.ok && consolidated?.sourceConsolidation) {
      lines.push(`Roll-forward ${step.fromYear} -> ${target}: VAT group continuity documented by Dinero year-opening consolidation to account ${consolidated.sourceConsolidation.destinationAccountNo}`);
    } else if (step.ok) {
      lines.push(`Roll-forward ${step.fromYear} -> ${target}: closing balances carry forward`);
    } else {
      lines.push(
        `Roll-forward BREAK ${step.fromYear} -> ${target}: ${step.breaks.length} account(s) do not carry forward`,
      );
      for (const b of step.breaks) {
        lines.push(
          `  account ${b.accountNo}: closing ${b.closingAmount} != opening ${b.openingAmount}`,
        );
      }
    }
    for (const group of step.vatGroups) {
      lines.push(
        `  VAT group ${group.group}: closing ${group.closingAmount}, opening ${group.openingAmount}, difference ${group.difference} (${group.accountNos.join(", ")}); ${group.status}${group.explanation ? ` by ${group.explanation.fiscalYear}/${group.explanation.voucher}` : ""}`,
      );
      if (group.explanation) for (const delta of group.explanation.perAccountDeltas) {
        lines.push(`    account ${delta.accountNo}: closing ${delta.closingAmount}, opening ${delta.openingAmount}, voucher delta ${delta.voucherAmount}`);
      }
      if (group.explanation) {
        lines.push(`    transfer ${group.explanation.sourceAccountNos.join(", ")} -> ${group.explanation.destinationAccountNo}: ${group.explanation.transferAmount}`);
      }
      if (group.sourceConsolidation) {
        for (const delta of group.sourceConsolidation.perAccountDeltas) {
          lines.push(`    account ${delta.accountNo}: closing ${delta.closingAmount}, opening ${delta.openingAmount}`);
        }
        lines.push(`    source year-opening consolidation -> ${group.sourceConsolidation.destinationAccountNo}`);
      }
    }
    for (const consolidation of step.sourceConsolidations ?? []) {
      lines.push(
        `  fixed-asset source group: closing ${consolidation.closingAmount}, opening ${consolidation.openingAmount}; consolidated to ${consolidation.destinationAccountNo}`,
      );
      for (const delta of consolidation.perAccountDeltas) {
        lines.push(`    account ${delta.accountNo}: closing ${delta.closingAmount}, opening ${delta.openingAmount}`);
      }
    }
  }
  for (const error of result.errors) lines.push(`Roll-forward check error: ${error}`);
  return lines;
}

