typeDefinitions.definition:
export type DineroPostingLine = {
  accountNo: string;
  debitAmount?: number;
  creditAmount?: number;
  vatCode?: string;
  text: string;
};

export type DineroPostingsResult = {
  ok: boolean;
  /** Vouchers posted, in the order they were posted. */
  posted: PostedVoucher[];
  /** Ordered, human-readable description of what happened. */
  auditTrail: string[];
  errors: string[];
};

export type DineroVoucher = {
  bilag: string;
  transactionDate: string;
  voucherType: string;
  text: string;
  lines: DineroPostingLine[];
};

export type PostedVoucher = {
  /** Source voucher reference (Dinero `Bilag`); the #196 receipt-link handle. */
  voucherRef: string;
  entryId: number;
  entryNo: string;
  transactionDate: string;
};

export type ImportHistoricalEntry = {
  transactionDate: string;
  text: string;
  lines: ImportOpeningBalanceLine[];
  /** Source-system voucher number (Dinero `Bilag`); links receipts in #196. */
  voucherRef?: string;
  /** Source-system entry classification (Dinero `Bilagstype`). */
  entryType?: string;
};

export type ImportOpeningBalanceLine = {
  accountNo: string;
  debitAmount?: number;
  creditAmount?: number;
  /** Optional per-line text; defaults to the account name when omitted. */
  text?: string;
  /** Optional source-system VAT code/label carried for the audit trail. */
  vatCode?: string;
};

