  createdBy?: string;
  createdByProgram?: string;
};

export type SettleInvoiceClaimsFromBankResult = JournalPostResult & {
  claimPaymentId?: number;
  invoiceNumber?: string;
  remainingClaimOpenBalance?: number;
};

