typeDefinitions.definition:
export type InvoicePaymentDetails = {
  bankName?: string | null;
  /** Danish 4-digit bank registration number (registreringsnummer). */
  registrationNo?: string | null;
  /** Danish bank account number (kontonummer). */
  accountNo?: string | null;
  iban?: string | null;
  /** Optional SWIFT/BIC for foreign transfers. */
  bic?: string | null;
  accountOwner?: string | null;
  customerNo?: string | null;
};

export type IssuedInvoicePdfPayload = InvoicePayload & {
  invoiceNumber?: string;
  issuedAt?: string;
  status?: string;
  /** Payment instructions; injected from ledger bank-account data on render. */
  payment?: InvoicePaymentDetails;
  /**
   * Lightweight brand mark. A short text string is rendered as a styled word
   * mark in the header. This is a deliberate minimal seam: an image-based logo
   * can be added later without changing the call sites.
   */
  logoText?: string | null;
};

export type RenderIssuedInvoicePdfInput = {
  invoiceDocumentId: number;
};

export type RenderIssuedInvoicePdfResult = {
  ok: boolean;
  renderDocumentId?: number;
  invoiceNumber?: string;
  storedPath?: string;
  sha256?: string;
  appliedRules: string[];
  errors: string[];
};

export type InvoiceBuyer = {
  name?: string;
  address?: string;
  vatOrCvr?: string;
  eanNumber?: string;
  publicRecipient?: boolean;
  /**
   * Peppol BIS 3.0 cbc:BuyerReference (BT-10). Mandatory for a public-recipient
   * e-invoice (PEPPOL-EN16931-R003) — the public authority's own reference
   * (often an "EAN-/ordrereference"). Without it the access point rejects the
   * invoice.
   */
  buyerReference?: string;
  /** Optional Peppol cac:OrderReference/cbc:ID (BT-13), the buyer's order id. */
  orderReference?: string;
};

export type InvoicePayload = {
  invoiceType: InvoiceType;
  vatTreatment?: VatTreatment;
  issueDate?: string;
  invoiceNumber?: string;
  seller?: { name?: string; address?: string; vatOrCvr?: string };
  buyer?: InvoiceBuyer;
  /**
   * Peppol cbc:InvoicedQuantity/@unitCode (UN/ECE Rec 20). Defaults to H87
   * ("piece") in the e-invoice export; set per payload to override.
   */
  unitCode?: string;
  lines?: Array<{ description?: string; quantity?: number; unitPriceExVat?: number; lineTotalExVat?: number; unitCode?: string; taxClassification?: VatLineClassification; vatRate?: number; reverseChargeBasis?: string }>;
  totals?: {
    netAmount?: number;
    vatRate?: number;
    vatAmount?: number;
    grossAmount?: number;
    fxRateToDkk?: number;
    netAmountDkk?: number;
    vatAmountDkk?: number;
    grossAmountDkk?: number;
    vatComputationBasis?: "VAT_20_OF_GROSS" | string;
  };
  reverseChargeBasis?: ReverseChargeBasis;
  reverseChargeNote?: string;
  currency?: string;
  dueDate?: string;
  deliveryDate?: string;
  deliveryPeriodStart?: string;
  deliveryPeriodEnd?: string;
};

export type ReverseChargeBasis =
  | "DK_MOMSLOVEN_§46_STK_1_NR_3"
  | "DK_MOMSLOVEN_§46_STK_1_NR_6"
  | "DK_MOMSLOVEN_§46_STK_1_NR_7"
  | "EU_MOMSDIREKTIV_ART_196"
  | "EU_MOMSDIREKTIV_ART_199";

