typeDefinitions.definition:
export type ResolveActorInput = {
  createdBy?: string | null;
  createdByProgram?: string | null;
  fallbackActor?: {
    createdBy: string;
    createdByProgram?: string;
  };
};

export type InvoiceBuyer = {
  name?: string;
  address?: string;
  vatOrCvr?: string;
  eanNumber?: string;
  publicRecipient?: boolean;
  /**
   * Peppol BIS 3.0 cbc:BuyerReference (BT-10). Mandatory for a public-recipient
   * e-invoice (PEPPOL-EN16931-R003) — the public authority's own reference
   * (often an "EAN-/ordrereference"). Without it the access point rejects the
   * invoice.
   */
  buyerReference?: string;
  /** Optional Peppol cac:OrderReference/cbc:ID (BT-13), the buyer's order id. */
  orderReference?: string;
};

export type InvoicePayload = {
  invoiceType: InvoiceType;
  vatTreatment?: VatTreatment;
  issueDate?: string;
  invoiceNumber?: string;
  seller?: { name?: string; address?: string; vatOrCvr?: string };
  buyer?: InvoiceBuyer;
  /**
   * Peppol cbc:InvoicedQuantity/@unitCode (UN/ECE Rec 20). Defaults to H87
   * ("piece") in the e-invoice export; set per payload to override.
   */
  unitCode?: string;
  lines?: Array<{ description?: string; quantity?: number; unitPriceExVat?: number; lineTotalExVat?: number; unitCode?: string; taxClassification?: VatLineClassification; vatRate?: number; reverseChargeBasis?: string }>;
  totals?: {
    netAmount?: number;
    vatRate?: number;
    vatAmount?: number;
    grossAmount?: number;
    fxRateToDkk?: number;
    netAmountDkk?: number;
    vatAmountDkk?: number;
    grossAmountDkk?: number;
    vatComputationBasis?: "VAT_20_OF_GROSS" | string;
  };
  reverseChargeBasis?: ReverseChargeBasis;
  reverseChargeNote?: string;
  currency?: string;
  dueDate?: string;
  deliveryDate?: string;
  deliveryPeriodStart?: string;
  deliveryPeriodEnd?: string;
};

export type ReverseChargeBasis =
  | "DK_MOMSLOVEN_§46_STK_1_NR_3"
  | "DK_MOMSLOVEN_§46_STK_1_NR_6"
  | "DK_MOMSLOVEN_§46_STK_1_NR_7"
  | "EU_MOMSDIREKTIV_ART_196"
  | "EU_MOMSDIREKTIV_ART_199";

export type IssueInvoiceResult = {
  ok: boolean;
  documentId?: DocumentId;
  invoiceNumber?: InvoiceNumber;
  storedPath?: string;
  sha256?: string;
  pdfDocumentId?: DocumentId;
  pdfStoredPath?: string;
  pdfSha256?: string;
  appliedRules: string[];
  errors: string[];
  // EJER-6: non-blocking advisories. Currently surfaces the case where the
  // invoice's issue date falls in an already-closed/reported accounting period
  // — the invoice document is fine, but the journal entry that books it will be
  // rejected by the period lock, so the owner is warned up front.
  warnings?: string[];
};

export type PreviewIssuedInvoicePdfResult =
  | { ok: true; pdfBytes: Uint8Array; invoiceNumber: string; appliedRules: string[]; errors: [] }
  | { ok: false; pdfBytes?: undefined; invoiceNumber?: undefined; appliedRules: string[]; errors: string[] };

