imports:
import {
  asDocumentId,
  asInvoiceNumber,
  type DocumentId,
  type InvoiceNumber,
} from "./ids";

typeDefinitions.definition:
export type AnnualReport = {
  ok: boolean;
  appliedRules: string[];
  /** Always "B" — this slice only covers regnskabsklasse B (micro/small). */
  regnskabsklasse: "B";
  fiscalYearStart: string;
  fiscalYearEnd: string;
  company: AnnualReportCompany;
  /** Resultatopgorelse for the fiscal year (reused from #176). */
  profitAndLoss: ProfitAndLossReport;
  /** Balance as of the fiscal-year end (reused from #176). */
  balanceSheet: BalanceSheetReport;
  /** Aarets resultat — the year's net result, DKK. Mirrors profitAndLoss.result. */
  aretsResultat: number;
  /**
   * Prior-year comparison figures (ÅRL §24). Present whenever the report is
   * assembled so the resultatopgorelse and balance can show both years.
   */
  comparison: AnnualReportComparison;
  /** Notes skeleton — placeholders the owner/advisor completes. */
  notes: AnnualReportNote[];
  ledelsespategning: AnnualReportLedelsespategning;
  /** Conservative claim: who prepared the report. */
  preparedBy: "Rentemester";
  /** Conservative-language disclaimer (Danish). */
  disclaimer: string;
  errors: string[];
};

export type AnnualReportCompany = {
  name: string;
  cvr: string;
  country: string;
  currency: string;
};

export type AnnualReportComparison = {
  fiscalYearStart: string;
  fiscalYearEnd: string;
  /** True when the preceding year contained any ledger activity. */
  available: boolean;
  totalIncome: number;
  totalExpense: number;
  aretsResultat: number;
  totalAssets: number;
  totalLiabilitiesAndEquity: number;
  equity: number;
};

export type AnnualReportLedelsespategning = {
  text: string;
  placeholder: boolean;
};

export type AnnualReportNote = {
  /** Stable note identifier, e.g. "accounting-policies". */
  id: string;
  /** Danish note heading. */
  title: string;
  /** Placeholder body — the owner/advisor completes the wording. */
  body: string;
  /** True while the note is an un-reviewed placeholder. */
  placeholder: boolean;
};

export type BalanceSheetReport = {
  ok: boolean;
  appliedRules: string[];
  asOfDate: string;
  assets: BalanceSheetSection;
  liabilities: BalanceSheetSection;
  /** Equity excluding the un-closed period result. */
  equity: BalanceSheetSection;
  /** Income − expense up to and including asOfDate, carried into equity. */
  periodResult: number;
  totalAssets: number;
  /** liabilities + equity + periodResult. */
  totalLiabilitiesAndEquity: number;
  /** True when totalAssets equals totalLiabilitiesAndEquity. */
  balanced: boolean;
  errors: string[];
};

export type BalanceSheetSection = {
  lines: StatementLine[];
  total: number;
};

export type ProfitAndLossReport = {
  ok: boolean;
  appliedRules: string[];
  periodStart: string;
  periodEnd: string;
  income: StatementLine[];
  expense: StatementLine[];
  totalIncome: number;
  totalExpense: number;
  /** totalIncome − totalExpense, DKK. Positive is a profit. */
  result: number;
  errors: string[];
};

export type StatementLine = {
  accountNo: string;
  name: string;
  type: AccountType;
  /** Amount in the statement's natural sign convention, DKK. */
  amount: number;
};

export type GenerateIxbrlResult = {
  ok: boolean;
  appliedRules: string[];
  /** The full XHTML+iXBRL document. Empty string on failure. */
  xhtml: string;
  /** sha256 of `xhtml`, for byte-stability checks and manifests. */
  sha256: string;
  /**
   * The resolved facts, in declared subset order. Exposed so callers (and the
   * golden test) can round-trip the document against the values that produced
   * it without re-parsing. Empty on failure.
   */
  facts: ResolvedFact[];
  /** The taxonomy subset name + version this document was generated against. */
  taxonomy: { name: string; version: string };
  errors: string[];
};

export type IxbrlSection =
  | "company-info"
  | "income-statement"
  | "balance-sheet"
  | "management-statement"
  | "accounting-policies";

export type IxbrlTaxonomyElement = {
  /** Namespaced element name, e.g. "ar:Revenue". */
  name: string;
  /** "monetary" -> ix:nonFraction; "text" -> ix:nonNumeric. */
  kind: "monetary" | "text";
  /** Human-readable Danish label rendered next to the fact. */
  label: string;
  /** Which class-B statement section this element belongs to. */
  section: IxbrlSection;
  /** The xbrli context the fact is reported against. */
  context: IxbrlContext;
};

export type IxbrlTaxonomySubset = {
  /** Clearly-versioned name, signalling this is a partial subset. */
  name: string;
  /** Semantic version of the subset; bump when elements change. */
  version: string;
  scope: string;
  prefix: string;
  namespace: string;
  elements: IxbrlTaxonomyElement[];
};

export type ResolvedFact = {
  element: IxbrlTaxonomyElement;
  /** Already-stringified value (formatted money or text). */
  value: string;
};

