export type Provision = {
  sourceId: string;
  ref: string;
  path: string[];
  kind: ProvisionKind;
  text: string;
  textHash: string;
};

type XmlNode = {
  name: string;
  attrs: Record<string, string>;
  children: XmlNode[];
  text: string;
};

