export type CvrCompanyInfo = {
  /** CVR number, 8 digits, no DK prefix. */
  cvr: string;
  name: string;
  /** Street line of the registered address (vejnavn + husnummer). */
  address: string | null;
  postalCode: string | null;
  city: string | null;
  municipalityCode: number | null;
  /** Numeric company-form code (60 = A/S, 80 = ApS, ...). */
  companyFormCode: number | null;
  /** Short company form, e.g. "ApS". */
  companyFormShort: string | null;
  /** Long company form, e.g. "Anpartsselskab". */
  companyFormLong: string | null;
  /** Company status, e.g. "NORMAL", "UNDER KONKURS". */
  status: string | null;
  industryCode: string | null;
  industryText: string | null;
  email: string | null;
  phone: string | null;
  website: string | null;
  /** Incorporation date, YYYY-MM-DD. */
  startDate: string | null;
  /** Fiscal-year start as a gMonthDay string, e.g. "--01-01". */
  fiscalYearStart: string | null;
  /** Fiscal-year end as a gMonthDay string, e.g. "--12-31". */
  fiscalYearEnd: string | null;
  /** Fiscal-year start month (1-12) derived from `fiscalYearStart`. */
  fiscalYearStartMonth: number | null;
  /** Whether statutory audit is opted out (REVISION_FRAVALGT). */
  auditWaived: boolean | null;
  /** Registered share capital, in the currency of `shareCapitalCurrency`. */
  shareCapital: number | null;
  shareCapitalCurrency: string | null;
  /** Latest reported employee headcount; CVR lags 1-2 years. */
  employees: number | null;
  /** True when the company opted out of marketing contact (reklamebeskyttet). */
  advertisingProtected: boolean;
  management: CvrManagementMember[];
};

export type CvrLookupOptions = {
  fetchImpl?: typeof fetch;
  /** Override the CVR Elasticsearch base URL (else RENTEMESTER_CVR_ENDPOINT). */
  endpoint?: string;
  username?: string;
  password?: string;
  /** Cache freshness window in days; default 30. */
  maxAgeDays?: number;
  /** Ignore a fresh cache entry and force a network fetch. */
  forceRefresh?: boolean;
  /** ISO timestamp treated as "now" — for deterministic tests. */
  asOf?: string;
  /** SEC-5: outgoing-request timeout in ms; default `DEFAULT_CVR_TIMEOUT_MS`. */
  timeoutMs?: number;
};

export type CvrManagementMember = {
  /** Person or company name of the management member. */
  name: string;
  /** Danish role label, e.g. "Direktion", "Bestyrelse", "FORMAND". */
  role: string;
};

export type DocumentMetadata = {
  source: string;
  documentType?: DocumentType;
  issueDate?: string;
  invoiceNo?: string;
  deliveryDescription?: string;
  amountIncVat?: number;
  currency?: string;
  sender?: { name?: string; address?: string; vatOrCvr?: string; countryCode?: string; identifierKind?: SupplierIdentifierKind };
  recipient?: { name?: string; address?: string; vatOrCvr?: string };
  vatAmount?: number;
  /** Purchase tax bases, retained verbatim with the voucher.  Omit for legacy uniform VAT documents. */
  purchaseVatLines?: PurchaseVatLine[];
  /** Human-confirmed invoice evidence required before a non-EU service can be
   * posted with automatic reverse-charge input-VAT deduction. */
  reverseChargeWordingConfirmed?: boolean;
  /** Explicit source fact: the issuer supplied a Danish simplified purchase invoice. */
  danishSimplifiedPurchaseInvoice?: boolean;
  paymentDetails?: string;
  exemptionCode?: DocumentExemptionCode;
  /** Imported bank row that is the immutable primary evidence for an internal voucher. */
  sourceBankTransactionId?: number;
  /** Human accounting explanation for why the internal voucher is booked. */
  accountingRationale?: string;
};

export type DocumentType =
  | "purchase_sale"
  | "cash_register_receipt"
  | "issued_invoice_pdf"
  | "internal_voucher";

export type InvoiceBuyer = {
  name?: string;
  address?: string;
  vatOrCvr?: string;
  eanNumber?: string;
  publicRecipient?: boolean;
  /**
   * Peppol BIS 3.0 cbc:BuyerReference (BT-10). Mandatory for a public-recipient
   * e-invoice (PEPPOL-EN16931-R003) — the public authority's own reference
   * (often an "EAN-/ordrereference"). Without it the access point rejects the
   * invoice.
   */
  buyerReference?: string;
  /** Optional Peppol cac:OrderReference/cbc:ID (BT-13), the buyer's order id. */
  orderReference?: string;
};

export type InvoicePayload = {
  invoiceType: InvoiceType;
  vatTreatment?: VatTreatment;
  issueDate?: string;
  invoiceNumber?: string;
  seller?: { name?: string; address?: string; vatOrCvr?: string };
  buyer?: InvoiceBuyer;
  /**
   * Peppol cbc:InvoicedQuantity/@unitCode (UN/ECE Rec 20). Defaults to H87
   * ("piece") in the e-invoice export; set per payload to override.
   */
  unitCode?: string;
  lines?: Array<{ description?: string; quantity?: number; unitPriceExVat?: number; lineTotalExVat?: number; unitCode?: string; taxClassification?: VatLineClassification; vatRate?: number; reverseChargeBasis?: string }>;
  totals?: {
    netAmount?: number;
    vatRate?: number;
    vatAmount?: number;
    grossAmount?: number;
    fxRateToDkk?: number;
    netAmountDkk?: number;
    vatAmountDkk?: number;
    grossAmountDkk?: number;
    vatComputationBasis?: "VAT_20_OF_GROSS" | string;
  };
  reverseChargeBasis?: ReverseChargeBasis;
  reverseChargeNote?: string;
  currency?: string;
  dueDate?: string;
  deliveryDate?: string;
  deliveryPeriodStart?: string;
  deliveryPeriodEnd?: string;
};

export type ReverseChargeBasis =
  | "DK_MOMSLOVEN_§46_STK_1_NR_3"
  | "DK_MOMSLOVEN_§46_STK_1_NR_6"
  | "DK_MOMSLOVEN_§46_STK_1_NR_7"
  | "EU_MOMSDIREKTIV_ART_196"
  | "EU_MOMSDIREKTIV_ART_199";

export type CreateCustomerInput = {
  name: string;
  address?: string;
  vatOrCvr?: string;
  email?: string;
  phone?: string;
  website?: string;
  eanNumber?: string;
  /** EJER-3: udeladt/null = ingen eksplicit frist — kunden arver virksomhedens profilfrist på fakturatidspunktet. */
  paymentTermsDays?: number | null;
  defaultCurrency?: string;
  notes?: string;
};

export type CreateVendorInput = {
  name: string;
  address?: string;
  vatOrCvr?: string;
  countryCode?: string;
  identifierKind?: SupplierIdentifierKind;
  email?: string;
  phone?: string;
  website?: string;
  defaultExpenseAccount?: string;
  defaultVatTreatment?: string;
  notes?: string;
};

export type CvrAutofillResult<T> =
  | { ok: true; input: T; company: CvrCompanyInfo }
  | { ok: false; errors: string[] };

export type UpdateCustomerInput = Partial<Omit<CreateCustomerInput, "name">> & {
  name?: string;
};

export type UpdateVendorInput = Partial<Omit<CreateVendorInput, "name">> & {
  name?: string;
};

