export type BankReconciliationFilters = {
  status?: ReconciliationStatus;
  textMatch?: string;
  amount?: number;
  // ===== BANK CLUSTER (#187) =====
  /** Restrict to a single bank account (numeric id). */
  bankAccountId?: number;
  // ===== END BANK CLUSTER (#187) =====
};

export type BankReconciliationReport = {
  ok: boolean;
  appliedRules: string[];
  periodStart: string;
  periodEnd: string;
  matchedCount: number;
  unmatchedCount: number;
  matchedAmountTotal: number;
  unmatchedAmountTotal: number;
  matched: Array<{
    bankTransactionId: number;
    transactionDate: string;
    text: string;
    amount: number;
    journalEntryId: number;
    journalEntryNo: string;
  }>;
  unmatched: Array<{
    bankTransactionId: number;
    transactionDate: string;
    text: string;
    amount: number;
    importBatchId: string | null;
  }>;
  errors: string[];
};

export type BankTransactionListResult = {
  ok: boolean;
  count: number;
  rows: Array<{
    id: number;
    transactionDate: string;
    bookingDate: string | null;
    text: string;
    amount: number;
    currency: string;
    reference: string | null;
    importBatchId: string | null;
    bankAccountId: number | null;
    ledgerStatus: string;
    reconciliationStatus: Exclude<ReconciliationStatus, "all">;
    journalEntryId: number | null;
    journalEntryNo: string | null;
  }>;
  errors: string[];
};

