export type ResolveActorInput = {
  createdBy?: string | null;
  createdByProgram?: string | null;
  fallbackActor?: {
    createdBy: string;
    createdByProgram?: string;
  };
};

export type RecurringDeliveryAdapter = {
  /** Local validation only. It must never attempt transport. */
  preflight: (input: { documentId: number; channel: DeliveryChannel }) =>
    Promise<{ ok: boolean; error?: string }>;
  /** Crosses the transport boundary exactly once after the DB reservation. */
  deliver: (input: { documentId: number; channel: DeliveryChannel }) =>
    Promise<RecurringDeliveryOutcome>;
  /** Status-only observation for an already accepted provider identity. */
  observePending?: (input: {
    documentId: number;
    channel: DeliveryChannel;
    providerId: string;
  }) => Promise<RecurringDeliveryOutcome>;
};

export type RecurringDeliveryOutcome = {
  status: RecurringDeliveryStatus;
  message?: string;
  /** Non-secret provider identity retained for status-only observation. */
  providerId?: string;
  /** Status/config/auth check failed; the accepted document remains pending. */
  observationFailed?: boolean;
};

export type RecurringDeliveryStatus =
  | "acknowledged"
  | "accepted_pending"
  | "terminal_failed"
  | "uncertain";

export type WorkspaceRecurringCompanyResult = {
  slug: string;
  status: "processed" | "skipped" | "failed";
  reason?: "archived" | "not initialized" | "run failed";
  generated?: number;
  attempted?: number;
  hasMore?: boolean;
  remainingGenerations?: number;
  continuation?: { remainingGenerations: number };
};

export type WorkspaceRecurringRunOptions = {
  asOfDate: string;
  actor: Required<Pick<ResolveActorInput, "createdBy" | "createdByProgram">>;
  maxGenerations?: number;
  /** Test/operations seam. It is never resolved from a workspace manifest. */
  adapterForCompany?: (input: { db: ReturnType<typeof openDb>; companyRoot: string; slug: string }) => RecurringDeliveryAdapter | undefined;
  runCompany?: (input: { db: ReturnType<typeof openDb>; companyRoot: string; slug: string }) => Promise<{ ok: boolean; generated: number; attempted: number; hasMore?: boolean; remainingGenerations?: number; continuation?: { remainingGenerations: number } }> | { ok: boolean; generated: number; attempted: number; hasMore?: boolean; remainingGenerations?: number; continuation?: { remainingGenerations: number } };
};

export type WorkspaceRecurringRunResult = {
  ok: boolean;
  companies: WorkspaceRecurringCompanyResult[];
  errors: string[];
  hasMore: boolean;
  remainingGenerations: number;
  continuation?: {
    remainingGenerations: number;
    companies: Array<{ slug: string; remainingGenerations: number }>;
  };
};

