  ok: boolean;
  asOf: string;
  appliedRules: string[];
  rows: RetentionStatusRow[];
  errors: string[];
};

export type RetentionStatusRow = {
  table: "documents" | "journal_entries" | "bank_transactions";
  total: number;
  expired: number;
  nextExpiry: string | null;
  oldestExpired: string | null;
};

