export type AnnualReport = {
  ok: boolean;
  appliedRules: string[];
  /** Always "B" — this slice only covers regnskabsklasse B (micro/small). */
  regnskabsklasse: "B";
  fiscalYearStart: string;
  fiscalYearEnd: string;
  company: AnnualReportCompany;
  /** Resultatopgorelse for the fiscal year (reused from #176). */
  profitAndLoss: ProfitAndLossReport;
  /** Balance as of the fiscal-year end (reused from #176). */
  balanceSheet: BalanceSheetReport;
  /** Aarets resultat — the year's net result, DKK. Mirrors profitAndLoss.result. */
  aretsResultat: number;
  /**
   * Prior-year comparison figures (ÅRL §24). Present whenever the report is
   * assembled so the resultatopgorelse and balance can show both years.
   */
  comparison: AnnualReportComparison;
  /** Notes skeleton — placeholders the owner/advisor completes. */
  notes: AnnualReportNote[];
  ledelsespategning: AnnualReportLedelsespategning;
  /** Conservative claim: who prepared the report. */
  preparedBy: "Rentemester";
  /** Conservative-language disclaimer (Danish). */
  disclaimer: string;
  errors: string[];
};

export type AnnualReportCompany = {
  name: string;
  cvr: string;
  country: string;
  currency: string;
};

export type AnnualReportComparison = {
  fiscalYearStart: string;
  fiscalYearEnd: string;
  /** True when the preceding year contained any ledger activity. */
  available: boolean;
  totalIncome: number;
  totalExpense: number;
  aretsResultat: number;
  totalAssets: number;
  totalLiabilitiesAndEquity: number;
  equity: number;
};

export type AnnualReportLedelsespategning = {
  text: string;
  placeholder: boolean;
};

export type AnnualReportNote = {
  /** Stable note identifier, e.g. "accounting-policies". */
  id: string;
  /** Danish note heading. */
  title: string;
  /** Placeholder body — the owner/advisor completes the wording. */
  body: string;
  /** True while the note is an un-reviewed placeholder. */
  placeholder: boolean;
};

export type BalanceSheetReport = {
  ok: boolean;
  appliedRules: string[];
  asOfDate: string;
  assets: BalanceSheetSection;
  liabilities: BalanceSheetSection;
  /** Equity excluding the un-closed period result. */
  equity: BalanceSheetSection;
  /** Income − expense up to and including asOfDate, carried into equity. */
  periodResult: number;
  totalAssets: number;
  /** liabilities + equity + periodResult. */
  totalLiabilitiesAndEquity: number;
  /** True when totalAssets equals totalLiabilitiesAndEquity. */
  balanced: boolean;
  errors: string[];
};

export type BalanceSheetSection = {
  lines: StatementLine[];
  total: number;
};

export type ProfitAndLossReport = {
  ok: boolean;
  appliedRules: string[];
  periodStart: string;
  periodEnd: string;
  income: StatementLine[];
  expense: StatementLine[];
  totalIncome: number;
  totalExpense: number;
  /** totalIncome − totalExpense, DKK. Positive is a profit. */
  result: number;
  errors: string[];
};

export type StatementLine = {
  accountNo: string;
  name: string;
  type: AccountType;
  /** Amount in the statement's natural sign convention, DKK. */
  amount: number;
};

export type AcontoTaxDeadline = {
  /** 1 = first ordinary installment (March), 2 = second (November). */
  installment: 1 | 2;
  /** Due date YYYY-MM-DD. */
  dueDate: string;
};

export type TaxAdjustment = {
  /** Stable adjustment identifier. */
  kind: "non_deductible_representation";
  /** Danish label. */
  label: string;
  /** Add-back amount, DKK. Positive increases taxable income above the bookkept result. */
  amount: number;
  /** Short Danish explanation of why the adjustment applies. */
  explanation: string;
};

export type TaxNeedsReview = {
  kind:
    | "depreciation_difference"
    | "tax_loss_carry_forward"
    | "company_form_out_of_scope";
  /** Danish label. */
  label: string;
  /** What the owner/advisor must determine. */
  requiredAction: string;
  /** Book depreciation posted in the year, DKK — present for depreciation_difference. */
  bookDepreciation?: number;
};

export type TaxReturn = {
  ok: boolean;
  appliedRules: string[];
  fiscalYearStart: string;
  fiscalYearEnd: string;
  /** Company form as recorded in master data (e.g. "ApS"), or "" if unknown. */
  companyForm: string;
  /** Årets resultat from the bookkept annual report, DKK. */
  bookkeptResult: number;
  /** The deterministic skattemæssige reguleringer applied. */
  adjustments: TaxAdjustment[];
  /** Sum of `adjustments[].amount`, DKK. */
  totalAdjustments: number;
  /** Skattepligtig indkomst = bookkeptResult + totalAdjustments, DKK. */
  taxableIncome: number;
  /** The corporate-tax rate applied (0.22) — echoed for traceability. */
  corporateTaxRate: number;
  /**
   * Selskabsskat = max(0, taxableIncome) × 22%, DKK. `null` when the company
   * form is outside the micro-ApS slice (a needs-review item is emitted instead).
   */
  corporateTax: number | null;
  /** Figures the slice deliberately did not compute — for owner/advisor review. */
  needsReview: TaxNeedsReview[];
  /**
   * Ordinary acontoskat installment deadlines for the income year (20 March and
   * 20 November). Informational — Rentemester does not compute or schedule the
   * acontoskat payment; it surfaces the deadlines so the owner does not miss
   * them.
   */
  acontoTaxDeadlines: AcontoTaxDeadline[];
  /** Conservative claim: who prepared the figures. */
  preparedBy: "Rentemester";
  /** Conservative-language disclaimer (Danish). */
  disclaimer: string;
  errors: string[];
};

