export type JournalPostResult = {
  ok: boolean;
  entryId?: JournalEntryId;
  entryNo?: string;
  entryHash?: string;
  appliedRules: string[];
  errors: string[];
};

export type LegacyVatEvidenceRow = {
  entry_id: number;
