};

export type VatRubric = {
  salgsmoms: number;
  momsAfVarekobUdland: number;
  momsAfYdelseskobUdland: number;
  kobsmoms: number;
  momstilsvar: number;
  rubrikA: number;
  rubrikB: number;
  rubrikC: number;
};

export type RepresentationPurchaseInput = {
  transactionDate: string;
  text: string;
  documentId: number;
  netAmount: number;
  expenseAccountNo?: string;
  paymentAccountNo?: string;
  sourceBankTransactionId?: number;
  currency?: string;
  amountForeign?: number;
  amountDkk?: number;
  fxRateToDkk?: number;
