export type NormalizedEuVat = {
  countryCode: string;
  vatNumber: string;
  normalized: string;
};

export type ValidateVatResult = {
  ok: boolean;
  validation?: ViesValidationRecord;
  appliedRules: string[];
  errors: string[];
};

export type ViesValidationRecord = NormalizedEuVat & {
  valid: boolean;
  name: string | null;
  address: string | null;
  validatedAt: string;
  expiresAt: string;
  rawResponse: string | null;
};

