export type DocumentMetadata = {
  source: string;
  documentType?: DocumentType;
  issueDate?: string;
  invoiceNo?: string;
  deliveryDescription?: string;
  amountIncVat?: number;
  currency?: string;
  sender?: { name?: string; address?: string; vatOrCvr?: string; countryCode?: string; identifierKind?: SupplierIdentifierKind };
  recipient?: { name?: string; address?: string; vatOrCvr?: string };
  vatAmount?: number;
  /** Purchase tax bases, retained verbatim with the voucher.  Omit for legacy uniform VAT documents. */
  purchaseVatLines?: PurchaseVatLine[];
  /** Human-confirmed invoice evidence required before a non-EU service can be
   * posted with automatic reverse-charge input-VAT deduction. */
  reverseChargeWordingConfirmed?: boolean;
  /** Explicit source fact: the issuer supplied a Danish simplified purchase invoice. */
  danishSimplifiedPurchaseInvoice?: boolean;
  paymentDetails?: string;
  exemptionCode?: DocumentExemptionCode;
  /** Imported bank row that is the immutable primary evidence for an internal voucher. */
  sourceBankTransactionId?: number;
  /** Human accounting explanation for why the internal voucher is booked. */
  accountingRationale?: string;
};

export type DocumentScanner = {
  scan(input: { bytes: Buffer; sha256: string; mimeType: string; filename: string; signal: AbortSignal }): Promise<
    | { ok: true; scannerId: string; scannerVersion?: string; evidenceRef?: string }
    | { ok: false; error?: string }
  >;
};

export type DocumentType =
  | "purchase_sale"
  | "cash_register_receipt"
  | "issued_invoice_pdf"
  | "internal_voucher";

export type IngestDocumentOptions = {
  forceDuplicateLogicalIdentity?: boolean;
  createdBy?: string;
  createdByProgram?: string;
  /** Internal bulk-import use only: the enclosing import writes one audit event. */
  suppressAudit?: boolean;
  /** Scanner policy is off unless a caller explicitly requires it. */
  scannerPolicy?: "off" | "required";
  /** Upper bound for a single scanner decision. Required scanners fail closed on expiry. */
  scannerTimeoutMs?: number;
  /** A vendor-neutral async seam. It receives immutable snapshot bytes only. */
  scanner?: DocumentScanner;
};

export type ImapClient = {
  /** Opens the connection, authenticates, and selects the target mailbox. */
  connect(): Promise<void>;
  /**
   * Returns the messages to consider for intake. `sinceUid` is an optional
   * lower bound a client MAY use to fetch only newer UIDs; correctness never
   * depends on it because dedup is content-keyed downstream — re-fetching an
   * already-ingested message is always safe.
   */
  fetchSince(sinceUid?: number): Promise<ImapMessage[]>;
  /** Closes the connection and releases the socket. */
  close(): Promise<void>;
};

export type ImapConfig = {
  host: string;
  port: number;
  username: string;
  password: string;
  /** TLS on connect (IMAPS). Defaults to true. */
  tls?: boolean;
  /** Mailbox to select. Defaults to "INBOX". */
  mailbox?: string;
};

export type ImapMessage = {
  /** Server-assigned UID — stable within a mailbox/uidvalidity window. */
  uid: number;
  /** Raw RFC-822 bytes of the message (headers + body). */
  raw: string | Buffer;
};

export type PollImapOptions = IngestMailDropOptions & {
  /** Optional UID lower bound forwarded to `ImapClient.fetchSince`. */
  sinceUid?: number;
};

export type IngestMailDropOptions = {
  /** Metadata applied to every ingested attachment. */
  metadata?: MailIntakeMetadataInput;
  /** Per-message metadata keyed on message-id; overrides `metadata`. */
  metadataPerMessage?: Record<string, MailIntakeMetadataInput>;
  /** Forwarded to ingestDocument for forced logical-duplicate scans. */
  ingestOptions?: IngestDocumentOptions;
  /**
   * #352 — Maks-størrelse pr. eml-fil i bytes. Default
   * `DEFAULT_MAX_EML_SIZE_BYTES`. Mails over grænsen får en
   * MAIL_INTAKE_TOO_LARGE-eksception i stedet for at blive parset.
   */
  maxEmlSizeBytes?: number;
  /**
   * SEC-9 (Audit 2026-06-11): OPTIONAL per-company sender allowlist. When
   * provided (and non-empty), a message whose `From:` address is not in the
   * list is refused with a `MAIL_INTAKE_SENDER_NOT_ALLOWED` exception instead of
   * being ingested — anyone who learns the company's intake address can no
   * longer drop arbitrary attachments into the ledger pipeline. Comparison is
   * case-insensitive on the bare `local@domain`. Default (undefined/empty) keeps
   * today's behaviour: every sender is accepted.
   */
  senderAllowlist?: string[];
  /**
   * SEC-9 (Audit 2026-06-11): OPTIONAL ceiling on how many messages a single
   * run will process. A flood of mail to the intake address cannot exhaust the
   * exception queue / disk in one pass; the remainder simply stay in the
   * maildrop for the next run. Default (undefined) keeps today's behaviour: the
   * whole maildrop is processed.
   */
  maxMessagesPerRun?: number;
};

