    { id: 30, name: ACCOUNTING_DIMENSION_LIFECYCLE_MIGRATION_NAME, checksum: ACCOUNTING_DIMENSION_LIFECYCLE_MIGRATION_CHECKSUM, artifact: ACCOUNTING_DIMENSION_LIFECYCLE_MIGRATION_ARTIFACT },
