          OR OLD.delivery_period_mode != NEW.delivery_period_mode
          OR OLD.payload_json != NEW.payload_json
          OR OLD.created_at != NEW.created_at
          OR NEW.next_issue_date < OLD.next_issue_date
          OR (OLD.active = 0 AND NEW.active = 1)
