    if (!sql || !new RegExp(`BEFORE\\s+${operation}\\s+ON\\s+rm_group_manifest_events`, "i").test(sql) || !/RAISE\s*\(\s*ABORT\s*,\s*'group manifest events are append-only'\s*\)/i.test(sql)) {
