export type WorkspaceControlPaths = {
  root: string;
  directory: string;
  db: string;
};

export function workspaceControlPaths(workspaceRoot: string): WorkspaceControlPaths {
  const directory = join(workspaceRoot, WORKSPACE_CONTROL_DIRECTORY);
